/**
 * lib/modsync — NX Labs catalog ingestion (agent K2). Provider-agnostic types.
 *
 * A Provider turns one upstream API into NormalizedMod records; the runner
 * upserts them idempotently (GameMod + ModVersion). Providers are RESUMABLE:
 * `run()` processes a bounded slice and returns a new cursor, so the worker
 * can interleave providers and survive restarts.
 */

export type ModChannel = "release" | "beta" | "alpha" | "snapshot";

export interface NormalizedVersion {
  versionId: string;
  versionNumber: string;
  channel: ModChannel;
  gameVersions: string[];
  loaders: string[];
  fileName?: string | null;
  fileUrl?: string | null;
  fileBytes?: number | null;
  sha1?: string | null;
  sha256?: string | null;
  sha512?: string | null;
  downloads?: number | null;
  changelog?: string | null;
  dependencies?: unknown;
  publishedAt?: Date | null;
}

export interface NormalizedMod {
  gameFamily: string;
  source: string; // GameMod.source vocabulary (modrinth, hangar, factorio_portal, ficsit, ...)
  sourceId: string; // stable provider id — the dedupe key with (gameFamily, source)
  slugHint: string; // preferred slug; runner resolves collisions
  name: string;
  category: string; // Nxeon coarse category (Mods, Plugins, Modpacks, ...)
  description?: string | null;
  /** Raw long body + its format; sanitised into bodyHtml by the runner. */
  body?: string | null;
  bodyFormat?: "markdown" | "html" | "bbcode";
  url?: string | null;
  sourceUrl?: string | null;
  iconUrl?: string | null;
  galleryUrls?: string[];
  authorName?: string | null;
  authorAvatarUrl?: string | null;
  license?: string | null; // SPDX id or provider's license name
  licenseUrl?: string | null;
  downloads?: number | null;
  followers?: number | null;
  categories?: string[];
  tags?: string[];
  gameVersions?: string[];
  loaders?: string[];
  serverSide?: string | null;
  appliesToVariant?: string | null;
  paid?: boolean;
  upstreamUpdatedAt?: Date | null;
  versions?: NormalizedVersion[];
}

export interface SyncContext {
  /** Rate-limited, backoff-aware fetch bound to this provider (lib/modsync/http.ts). */
  http: import("./http").HttpClient;
  /** Cursor from the previous slice (null on a fresh run). */
  cursor: Record<string, unknown> | null;
  /** "full" = walk the whole popular slice; "recent" = only newest-updated pages (cheap freshness pass). */
  mode: "full" | "recent";
  /** Budget for this slice. */
  maxMods: number;
  deadline: number; // epoch ms — stop starting new pages after this
  log: (msg: string) => void;
  /** Hand a batch to the runner for upserting. */
  emit: (mods: NormalizedMod[]) => Promise<void>;
  /** True if the operator paused/disabled the provider mid-run. */
  shouldStop: () => Promise<boolean>;
}

export interface SliceResult {
  /** New cursor to resume from; null when the full pass finished. */
  cursor: Record<string, unknown> | null;
  done: boolean;
}

export interface Provider {
  key: string;
  label: string;
  /** Games this provider can supply. */
  games: string[];
  /** Requests/min ceiling we self-impose (under the upstream's published limit). */
  ratePerMin: number;
  /** Default minutes between full passes. */
  intervalMinutes: number;
  /** Off by default pending owner/ToS action (e.g. uMod). */
  defaultEnabled: boolean;
  /** Human verdict summary mirrored from docs/MODS-SOURCES.md. */
  policy: "mirror-if-licensed" | "metadata-only";
  run(ctx: SyncContext): Promise<SliceResult>;
}
import type { Provider } from "./types";
import { modrinth } from "./providers/modrinth";
import { hangar } from "./providers/hangar";
import { factorio } from "./providers/factorio";
import { ficsit } from "./providers/ficsit";

/** Native modsync providers. Order = scheduling priority. */
export const PROVIDERS: Provider[] = [modrinth, hangar, ficsit, factorio];
export const providerByKey = (k: string) => PROVIDERS.find((p) => p.key === k) ?? null;

/**
 * Providers that already have a legacy importer in scripts/ (run weekly by
 * scripts/weekly-mod-catalog-refresh.sh). The admin page shows their row counts
 * + freshness read-only; they get native modsync providers incrementally.
 * `verdict` mirrors docs/MODS-SOURCES.md.
 */
export const LEGACY_SOURCES: { source: string; label: string; verdict: string }[] = [
  { source: "steam_workshop", label: "Steam Workshop", verdict: "metadata only — never redistribute" },
  { source: "mod_io", label: "mod.io", verdict: "metadata only (API key, ToS)" },
  { source: "thunderstore", label: "Thunderstore", verdict: "metadata + link-through (no per-package license)" },
  { source: "vintagestory_moddb", label: "Vintage Story ModDB", verdict: "metadata + link-through" },
  { source: "reforger_workshop", label: "Arma Reforger Workshop", verdict: "metadata only" },
  { source: "github", label: "GitHub", verdict: "metadata only here (license per repo)" },
  { source: "umod", label: "uMod / Oxide", verdict: "DISABLED pending ToS (Cloudflare-blocked)" },
];
import fs from "node:fs/promises";
import path from "node:path";

/** Root of the NX Labs local store (mod files + cached images). On this host: a quota'd dataset on the 3 TB `tank` pool, NOT the 49 GB root disk. */
export function mirrorDir(): string {
  return process.env.NXLABS_MIRROR_DIR || "/tank/nxlabs-mirror";
}
/** Total bytes of mod FILES we allow ourselves (the owner's ~100 GB). Images are budgeted separately and are tiny. */
export function mirrorMaxBytes(): number {
  const v = Number(process.env.NXLABS_MIRROR_MAX_BYTES);
  return Number.isFinite(v) && v > 0 ? v : 100 * 1024 ** 3;
}
/** Hard per-file ceiling: bigger artifacts (modpacks) are link-through only. */
export function mirrorMaxFileBytes(): number {
  const v = Number(process.env.NXLABS_MIRROR_MAX_FILE_BYTES);
  return Number.isFinite(v) && v > 0 ? v : 150 * 1024 ** 2;
}
export const filesRoot = () => path.join(mirrorDir(), "files");
export const imagesRoot = () => path.join(mirrorDir(), "img");
export const tmpRoot = () => path.join(mirrorDir(), "tmp");

let readyCache: { at: number; ok: boolean } | null = null;
/**
 * The mirror root must ALREADY EXIST (provisioned by the owner as its own quota'd
 * dataset). We never mkdir it ourselves: on a host where /tank is not mounted that
 * would silently fill the 49 GB root disk. When it is missing, image caching and
 * file mirroring are skipped (metadata + hotlinks keep working).
 */
export async function mirrorReady(): Promise<boolean> {
  if (readyCache && Date.now() - readyCache.at < 30_000) return readyCache.ok;
  let ok = false;
  try {
    ok = (await fs.stat(mirrorDir())).isDirectory();
  } catch {}
  readyCache = { at: Date.now(), ok };
  return ok;
}
/**
 * Polite HTTP for upstream mod APIs: identifying User-Agent, token-bucket
 * pacing, exponential backoff with jitter, Retry-After honouring, and
 * ETag / If-Modified-Since conditional requests. No upstream is ever hit
 * faster than its provider's `ratePerMin`.
 */

export const MODSYNC_UA = "NxeonModSync/1.0 (+https://nxeon.cloud; mods@nxeon.cloud)";

export interface HttpOptions {
  ratePerMin: number;
  maxRetries?: number;
  headers?: Record<string, string>;
  fetchImpl?: typeof fetch;
  sleep?: (ms: number) => Promise<void>;
  now?: () => number;
}

export interface CondOpts {
  etag?: string | null;
  lastModified?: string | null;
}

export class HttpError extends Error {
  constructor(public status: number, public url: string, msg?: string) {
    super(msg ?? `HTTP ${status} for ${url}`);
  }
}

export class HttpClient {
  private nextSlot = 0;
  private readonly gap: number;
  private readonly fetchImpl: typeof fetch;
  private readonly sleep: (ms: number) => Promise<void>;
  private readonly now: () => number;
  requests = 0;
  retries = 0;

  constructor(private opts: HttpOptions) {
    this.gap = Math.ceil(60_000 / Math.max(1, opts.ratePerMin));
    this.fetchImpl = opts.fetchImpl ?? fetch;
    this.sleep = opts.sleep ?? ((ms) => new Promise((r) => setTimeout(r, ms)));
    this.now = opts.now ?? Date.now;
  }

  private async pace() {
    const t = this.now();
    const wait = Math.max(0, this.nextSlot - t);
    this.nextSlot = Math.max(t, this.nextSlot) + this.gap;
    if (wait > 0) await this.sleep(wait);
  }

  /** Backoff delay for attempt n (0-based): 1s,2s,4s,... capped 60s, +jitter. */
  static backoffMs(attempt: number, retryAfter?: string | null, rnd = Math.random): number {
    if (retryAfter) {
      const s = Number(retryAfter);
      if (Number.isFinite(s) && s >= 0) return Math.min(120_000, s * 1000 + 250);
      const d = Date.parse(retryAfter);
      if (Number.isFinite(d)) return Math.min(120_000, Math.max(0, d - Date.now()) + 250);
    }
    return Math.min(60_000, 1000 * 2 ** attempt) + Math.floor(rnd() * 400);
  }

  /** Raw request with pacing + retry on 429/5xx/network errors. 304 is returned as-is. */
  async request(url: string, init: RequestInit & { cond?: CondOpts; maxRetries?: number } = {}): Promise<Response> {
    const maxRetries = init.maxRetries ?? this.opts.maxRetries ?? 5;
    const headers: Record<string, string> = {
      "User-Agent": MODSYNC_UA,
      Accept: "application/json",
      ...(this.opts.headers ?? {}),
      ...((init.headers as Record<string, string>) ?? {}),
    };
    if (init.cond?.etag) headers["If-None-Match"] = init.cond.etag;
    if (init.cond?.lastModified) headers["If-Modified-Since"] = init.cond.lastModified;
    let lastErr: unknown;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      await this.pace();
      this.requests++;
      try {
        const res = await this.fetchImpl(url, { ...init, headers, signal: init.signal ?? AbortSignal.timeout(60_000) });
        if (res.status === 429 || res.status >= 500) {
          lastErr = new HttpError(res.status, url);
          if (attempt === maxRetries) throw lastErr;
          this.retries++;
          const ra = res.headers.get("retry-after");
          try { await res.arrayBuffer(); } catch {}
          await this.sleep(HttpClient.backoffMs(attempt, ra));
          continue;
        }
        return res;
      } catch (e) {
        if (e instanceof HttpError) throw e;
        lastErr = e;
        if (attempt === maxRetries) throw e;
        this.retries++;
        await this.sleep(HttpClient.backoffMs(attempt));
      }
    }
    throw lastErr;
  }

  async json<T>(url: string, init: RequestInit = {}): Promise<T> {
    const res = await this.request(url, init);
    if (!res.ok) throw new HttpError(res.status, url);
    return (await res.json()) as T;
  }

  /** Conditional GET. Returns null on 304 (unchanged). */
  async jsonConditional<T>(url: string, cond: CondOpts): Promise<{ data: T; etag: string | null; lastModified: string | null } | null> {
    const res = await this.request(url, { cond });
    if (res.status === 304) return null;
    if (!res.ok) throw new HttpError(res.status, url);
    return { data: (await res.json()) as T, etag: res.headers.get("etag"), lastModified: res.headers.get("last-modified") };
  }
}
/**
 * License policy for the local mirror. We ONLY store a mod's FILE when its
 * declared license grants redistribution. Everything else is metadata +
 * link-through. Conservative by design: unknown/empty/"all rights reserved"
 * => not redistributable.
 */

const OPEN_SPDX = new Set([
  "mit", "mit-0", "apache-2.0", "bsd-2-clause", "bsd-3-clause", "bsd-3-clause-clear", "isc", "unlicense",
  "cc0-1.0", "zlib", "0bsd", "mpl-2.0", "lgpl-2.1", "lgpl-2.1-only", "lgpl-2.1-or-later", "lgpl-3.0",
  "lgpl-3.0-only", "lgpl-3.0-or-later", "gpl-2.0", "gpl-2.0-only", "gpl-2.0-or-later", "gpl-3.0",
  "gpl-3.0-only", "gpl-3.0-or-later", "agpl-3.0", "agpl-3.0-only", "agpl-3.0-or-later", "cc-by-4.0",
  "cc-by-sa-4.0", "cc-by-3.0", "cc-by-sa-3.0", "artistic-2.0", "bsl-1.0", "epl-2.0", "eupl-1.2",
]);

/** Free-text names some providers use (Hangar's license.type) mapped to the SPDX family. */
const NAME_ALIASES: Record<string, string> = {
  mit: "mit", "mit license": "mit", apache: "apache-2.0", "apache 2.0": "apache-2.0", "apache-2.0": "apache-2.0",
  gpl: "gpl-3.0", gplv3: "gpl-3.0", "gpl-3.0": "gpl-3.0", gplv2: "gpl-2.0", lgpl: "lgpl-3.0", agpl: "agpl-3.0",
  bsd: "bsd-3-clause", "bsd-3": "bsd-3-clause", mpl: "mpl-2.0", unlicense: "unlicense", cc0: "cc0-1.0", isc: "isc",
};

export function normalizeLicense(raw: string | null | undefined): string | null {
  const t = (raw ?? "").trim();
  return t ? t : null;
}

export function isRedistributable(license: string | null | undefined): boolean {
  const t = normalizeLicense(license)?.toLowerCase();
  if (!t) return false;
  if (t.includes("licenseref") || t.includes("reserved") || t.includes("proprietary") || t === "other" || t === "custom") return false;
  if (OPEN_SPDX.has(t)) return true;
  const alias = NAME_ALIASES[t];
  return !!alias && OPEN_SPDX.has(alias);
}
/**
 * Idempotent persistence of NormalizedMod -> GameMod + ModVersion.
 * Dedupe key: (gameFamily, source, sourceId); falls back to the existing
 * @@unique([gameFamily, slug]) with collision-suffixing, same convention as the
 * legacy scripts/import-*.ts so re-ingesting rows those scripts created
 * UPDATES them instead of duplicating.
 */
import { db } from "../db";
import { renderModBody } from "../mod-markdown";
import type { HttpClient } from "./http";
import { cacheImage, ICON_SIZE, SHOT_SIZE } from "./images";
import { isRedistributable, normalizeLicense } from "./license";
import type { NormalizedMod } from "./types";

export function slugify(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80) || "mod";
}

const GALLERY_CAP = 8;
const VERSION_CAP = 25; // newest N builds per mod: enough for the compat matrix, bounded rows

export interface UpsertOpts {
  http?: HttpClient; // required for image caching
  cacheImages?: boolean;
  /** Pre-fetched set of slugs in use for the family (perf for big batches). */
}

export async function upsertMod(m: NormalizedMod, opts: UpsertOpts = {}): Promise<"created" | "updated"> {
  const existing = await db.gameMod.findFirst({
    where: { gameFamily: m.gameFamily, source: m.source, sourceId: m.sourceId },
    select: { id: true, slug: true, iconUrl: true, iconKey: true, galleryUrls: true, galleryKeys: true },
  });
  const license = normalizeLicense(m.license);
  const gallery = (m.galleryUrls ?? []).filter((u) => /^https:\/\//i.test(u)).slice(0, GALLERY_CAP);

  let iconKey = existing?.iconUrl === (m.iconUrl ?? null) ? existing?.iconKey ?? null : null;
  let galleryKeys = existing && JSON.stringify(existing.galleryUrls) === JSON.stringify(gallery) ? existing.galleryKeys : [];
  if (opts.cacheImages && opts.http) {
    if (m.iconUrl && !iconKey) iconKey = await cacheImage(opts.http, m.iconUrl, ICON_SIZE);
    if (gallery.length && galleryKeys.length !== gallery.length) {
      const keys: string[] = [];
      for (const g of gallery.slice(0, 4)) {
        const k = await cacheImage(opts.http, g, SHOT_SIZE);
        if (k) keys.push(k);
      }
      galleryKeys = keys;
    }
  }

  const body = m.body?.trim() ? m.body : null;
  const bodyHtml = body
    ? renderModBody(body, m.bodyFormat === "markdown" ? "modrinth" : "other", 12000).html
    : null;

  const versions = m.versions ?? [];
  const latest = versions[0];
  const data = {
    name: m.name.slice(0, 200),
    category: m.category,
    description: m.description?.slice(0, 600) || null,
    longDescription: body,
    bodyHtml,
    url: m.url ?? null,
    sourceUrl: m.sourceUrl ?? null,
    iconUrl: m.iconUrl ?? null,
    iconKey,
    galleryUrls: gallery,
    galleryKeys,
    authorName: m.authorName ?? null,
    authorAvatarUrl: m.authorAvatarUrl ?? null,
    license,
    licenseUrl: m.licenseUrl ?? null,
    redistributable: isRedistributable(license),
    downloads: m.downloads ?? null,
    followers: m.followers ?? null,
    categories: m.categories ?? [],
    tags: m.tags ?? [],
    gameVersions: m.gameVersions ?? [],
    loaders: m.loaders ?? [],
    serverSide: m.serverSide ?? null,
    appliesToVariant: m.appliesToVariant ?? null,
    paid: m.paid ?? false,
    latestVersion: latest?.versionNumber ?? null,
    upstreamUpdatedAt: m.upstreamUpdatedAt ?? null,
    source: m.source,
    sourceId: m.sourceId,
    upstreamOk: true,
    upstreamNote: null,
    verifiedAt: new Date(),
    syncedAt: new Date(),
  };

  let id: string;
  let result: "created" | "updated";
  if (existing) {
    // Never blank something we already know: partial provider passes (e.g. no
    // author avatar in a search hit) must not erase earlier enrichment.
    const patch: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(data)) {
      if (v === null || v === undefined || (Array.isArray(v) && v.length === 0)) continue;
      patch[k] = v;
    }
    await db.gameMod.update({ where: { id: existing.id }, data: patch });
    id = existing.id;
    result = "updated";
  } else {
    let slug = m.slugHint || slugify(m.name);
    for (let i = 2; await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: m.gameFamily, slug } }, select: { id: true } }); i++) {
      slug = `${m.slugHint || slugify(m.name)}-${i}`;
      if (i > 50) throw new Error(`slug exhaustion for ${m.name}`);
    }
    const row = await db.gameMod.create({ data: { gameFamily: m.gameFamily, slug, active: true, ...data }, select: { id: true } });
    id = row.id;
    result = "created";
  }

  for (const v of versions.slice(0, VERSION_CAP)) {
    const vd = {
      versionNumber: v.versionNumber.slice(0, 120),
      channel: v.channel,
      gameVersions: v.gameVersions,
      loaders: v.loaders,
      fileName: v.fileName ?? null,
      fileUrl: v.fileUrl ?? null,
      fileBytes: v.fileBytes ?? null,
      sha1: v.sha1 ?? null,
      sha256: v.sha256 ?? null,
      sha512: v.sha512 ?? null,
      downloads: v.downloads ?? null,
      changelog: v.changelog?.slice(0, 8000) || null,
      dependencies: (v.dependencies ?? undefined) as never,
      publishedAt: v.publishedAt ?? null,
    };
    await db.modVersion.upsert({
      where: { gameModId_versionId: { gameModId: id, versionId: v.versionId } },
      update: vd,
      create: { gameModId: id, versionId: v.versionId, ...vd },
    });
  }
  return result;
}
/**
 * Hangar (PaperMC plugin repository) — game: minecraft. Public REST API
 * https://hangar.papermc.io/api-docs. Plugin license is declared per project
 * (`settings.license`); file stored only when it maps to an open SPDX family.
 * One list call returns 25 projects incl. their README + supported versions;
 * versions need one extra call per project (limited to the popular slice).
 */
import type { NormalizedMod, NormalizedVersion, Provider, SliceResult, SyncContext } from "../types";

const API = "https://hangar.papermc.io/api/v1";
const PAGE = 25;

export interface HgProject {
  id: string | number; name: string; namespace: { owner: string; slug: string }; description?: string;
  category?: string; lastUpdated?: string; mainPageContent?: string; avatarUrl?: string | null; memberNames?: string[];
  stats?: { downloads?: number; stars?: number; watchers?: number };
  settings?: { license?: { name?: string; url?: string | null; type?: string | null }; keywords?: string[]; tags?: string[]; links?: { links?: { name: string; url: string }[] }[] };
  supportedPlatforms?: Record<string, string[]>;
}
export interface HgVersion {
  id: string | number; name: string; createdAt: string; channel?: { name?: string };
  description?: string; stats?: { totalDownloads?: number };
  downloads?: Record<string, { fileInfo?: { name: string; sizeBytes: number; sha256Hash: string } | null; externalUrl?: string | null; downloadUrl?: string | null }>;
  platformDependencies?: Record<string, string[]>;
  pluginDependencies?: Record<string, { name: string; required: boolean }[]>;
}

export function parseHangarVersion(v: HgVersion): NormalizedVersion {
  const plats = Object.keys(v.downloads ?? {});
  const primary = (v.downloads ?? {})["PAPER"] ?? (v.downloads ?? {})[plats[0]];
  const ch = (v.channel?.name ?? "release").toLowerCase();
  const gv = [...new Set(Object.values(v.platformDependencies ?? {}).flat())];
  return {
    versionId: String(v.id),
    versionNumber: v.name,
    channel: ch.includes("snapshot") ? "snapshot" : ch.includes("beta") ? "beta" : ch.includes("alpha") ? "alpha" : "release",
    gameVersions: gv,
    loaders: plats.map((p) => p.toLowerCase()),
    fileName: primary?.fileInfo?.name ?? null,
    // externalUrl = hosted elsewhere (link-through only); downloadUrl = Hangar CDN.
    fileUrl: primary?.downloadUrl ?? null,
    fileBytes: primary?.fileInfo?.sizeBytes ?? null,
    sha256: primary?.fileInfo?.sha256Hash ?? null,
    downloads: v.stats?.totalDownloads ?? null,
    changelog: v.description || null,
    dependencies: v.pluginDependencies ?? {},
    publishedAt: v.createdAt ? new Date(v.createdAt) : null,
  };
}

export function parseHangarProject(p: HgProject, versions: HgVersion[]): NormalizedMod {
  const ns = p.namespace;
  const lic = p.settings?.license;
  const links = (p.settings?.links ?? []).flatMap((l) => l.links ?? []);
  const src = links.find((l) => /^source/i.test(l.name))?.url ?? null;
  const supported = p.supportedPlatforms ?? {};
  return {
    gameFamily: "minecraft",
    source: "hangar",
    sourceId: `${ns.owner}/${ns.slug}`,
    slugHint: `${ns.slug.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`,
    name: p.name,
    category: "Plugins",
    description: p.description || null,
    body: p.mainPageContent || null,
    bodyFormat: "markdown",
    url: `https://hangar.papermc.io/${ns.owner}/${ns.slug}`,
    sourceUrl: src,
    iconUrl: p.avatarUrl ?? null,
    authorName: ns.owner,
    license: lic?.type && lic.type !== "Other" ? lic.type : lic?.name || null,
    licenseUrl: lic?.url ?? null,
    downloads: p.stats?.downloads ?? null,
    followers: p.stats?.stars ?? null,
    categories: p.category ? [p.category] : [],
    tags: [...(p.settings?.keywords ?? []), ...(p.settings?.tags ?? []).map((t) => t.toLowerCase())],
    gameVersions: [...new Set(Object.values(supported).flat())],
    loaders: Object.keys(supported).map((x) => x.toLowerCase()),
    serverSide: "required",
    appliesToVariant: "paper",
    upstreamUpdatedAt: p.lastUpdated ? new Date(p.lastUpdated) : null,
    versions: versions.map(parseHangarVersion),
  };
}

export const hangar: Provider = {
  key: "hangar",
  label: "Hangar (PaperMC)",
  games: ["minecraft"],
  ratePerMin: 60,
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "mirror-if-licensed",
  async run(ctx: SyncContext): Promise<SliceResult> {
    let offset = Number(ctx.cursor?.offset ?? 0);
    const versionTop = Number(process.env.MODSYNC_HANGAR_VERSION_TOP ?? 1500);
    let produced = 0;
    while (true) {
      if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { offset }, done: false };
      const sort = ctx.mode === "recent" ? "-updated" : "-downloads";
      const page = await ctx.http.json<{ result: HgProject[]; pagination: { count: number } }>(`${API}/projects?limit=${PAGE}&offset=${offset}&sort=${sort}`);
      if (!page.result.length) return { cursor: null, done: true };
      const mods: NormalizedMod[] = [];
      for (const p of page.result) {
        let versions: HgVersion[] = [];
        if (offset < versionTop) {
          try {
            const r = await ctx.http.json<{ result: HgVersion[] }>(`${API}/projects/${encodeURIComponent(p.namespace.owner)}/${encodeURIComponent(p.namespace.slug)}/versions?limit=5&offset=0`);
            versions = r.result;
          } catch (e) {
            ctx.log(`hangar versions failed for ${p.namespace.slug}: ${e instanceof Error ? e.message : e}`);
          }
        }
        mods.push(parseHangarProject(p, versions));
      }
      await ctx.emit(mods);
      produced += mods.length;
      offset += PAGE;
      ctx.log(`hangar offset=${offset}/${page.pagination.count}`);
      if (offset >= page.pagination.count) return { cursor: null, done: true };
      if (ctx.mode === "recent" && offset >= PAGE * 8) return { cursor: null, done: true };
    }
  },
};

