/**
 * Scheduler core: runs ONE bounded slice of one provider, resumable via the
 * ModSyncProvider.cursor. Safe to call concurrently from several processes
 * (claim = conditional UPDATE on the provider row with a heartbeat window).
 */
import { db } from "../db";
import { HttpClient } from "./http";
import { PROVIDERS, providerByKey } from "./registry";
import { mirrorVersion } from "./mirror";
import { upsertMod } from "./store";
import type { NormalizedMod, Provider } from "./types";
import { Prisma } from "@prisma/client";

const STALE_RUNNING_MS = 20 * 60_000;
const FULL_EVERY_MS = 7 * 24 * 3600_000;

export interface SliceOpts {
  maxMods?: number;
  budgetMs?: number;
  /** Ignore paused/enabled/nextRunAt (admin "run now" or CLI). */
  force?: boolean;
  mode?: "full" | "recent";
  cacheImages?: boolean;
  mirror?: boolean;
  mirrorLimit?: number;
  log?: (m: string) => void;
}

export interface SliceStats {
  seen: number; created: number; updated: number; failed: number; requests: number; retries: number;
  mirrored: number; mirrorSkipped: number; mirrorFailed: number; mode: string; done: boolean; fullAt?: string | null;
}

export async function ensureProviderRows(): Promise<void> {
  for (const p of PROVIDERS) {
    await db.modSyncProvider.upsert({
      where: { key: p.key },
      update: {},
      create: { key: p.key, enabled: p.defaultEnabled, intervalMinutes: p.intervalMinutes, nextRunAt: new Date() },
    });
  }
}

/** Pick the next provider that is due (or has a pending run request). */
export async function nextDueProvider(): Promise<string | null> {
  await ensureProviderRows();
  const now = new Date();
  const rows = await db.modSyncProvider.findMany({ where: { enabled: true, paused: false }, orderBy: { nextRunAt: "asc" } });
  for (const r of rows) {
    if (!providerByKey(r.key)) continue;
    const running = r.lastStatus === "running" && r.lastRunAt && now.getTime() - r.lastRunAt.getTime() < STALE_RUNNING_MS;
    if (running) continue;
    if (r.runRequested || !r.nextRunAt || r.nextRunAt <= now) return r.key;
  }
  return null;
}

export async function runProviderSlice(key: string, opts: SliceOpts = {}): Promise<SliceStats> {
  const provider = providerByKey(key);
  if (!provider) throw new Error(`unknown provider ${key}`);
  const log = opts.log ?? (() => {});
  await ensureProviderRows();
  const row = await db.modSyncProvider.findUniqueOrThrow({ where: { key } });
  if (!opts.force && (!row.enabled || row.paused)) throw new Error(`${key} is ${row.paused ? "paused" : "disabled"}`);

  // Claim: only one runner may hold "running" within the heartbeat window.
  const claimed = await db.modSyncProvider.updateMany({
    where: {
      key,
      OR: [{ lastStatus: { not: "running" } }, { lastStatus: null }, { lastRunAt: { lt: new Date(Date.now() - STALE_RUNNING_MS) } }],
    },
    data: { lastStatus: "running", lastRunAt: new Date(), runRequested: false },
  });
  if (claimed.count === 0) throw new Error(`${key} is already running`);

  const run = await db.modSyncRun.create({ data: { providerKey: key } });
  const prevCursor = (row.cursor as Record<string, unknown> | null) ?? null;
  const prevStats = (row.lastStats as Record<string, unknown> | null) ?? null;
  const fullAtPrev = prevStats?.fullAt ? Date.parse(String(prevStats.fullAt)) : 0;
  const mode: "full" | "recent" = opts.mode ?? (prevCursor?.__mode as "full" | "recent" | undefined) ?? (Date.now() - fullAtPrev > FULL_EVERY_MS ? "full" : "recent");

  const http = new HttpClient({
    ratePerMin: provider.ratePerMin,
    headers: key === "modrinth" && process.env.MODRINTH_API_KEY ? { Authorization: process.env.MODRINTH_API_KEY } : {},
  });
  const cdn = new HttpClient({ ratePerMin: 240 });
  const stats: SliceStats = { seen: 0, created: 0, updated: 0, failed: 0, requests: 0, retries: 0, mirrored: 0, mirrorSkipped: 0, mirrorFailed: 0, mode, done: false, fullAt: row.lastStats ? (prevStats?.fullAt as string | undefined) ?? null : null };
  const errors: string[] = [];
  const deadline = Date.now() + (opts.budgetMs ?? 8 * 60_000);

  const emit = async (mods: NormalizedMod[]) => {
    for (let i = 0; i < mods.length; i += 4) {
      await Promise.all(
        mods.slice(i, i + 4).map(async (m) => {
          stats.seen++;
          try {
            const r = await upsertMod(m, { http: cdn, cacheImages: opts.cacheImages !== false });
            stats[r]++;
          } catch (e) {
            stats.failed++;
            if (errors.length < 5) errors.push(`${m.sourceId}: ${e instanceof Error ? e.message : e}`);
          }
        }),
      );
    }
    // heartbeat so a long slice isn't treated as stale
    await db.modSyncProvider.update({ where: { key }, data: { lastRunAt: new Date() } }).catch(() => {});
  };
  const shouldStop = async () => {
    const r = await db.modSyncProvider.findUnique({ where: { key }, select: { paused: true, enabled: true } });
    return !!r && (r.paused || !r.enabled) && !opts.force;
  };

  let status = "ok";
  let errorText: string | null = null;
  let cursor: Record<string, unknown> | null = null;
  try {
    const cur = prevCursor ? (({ __mode, ...c }) => c)(prevCursor as Record<string, unknown>) : null;
    const res = await provider.run({ http, cursor: cur, mode, maxMods: opts.maxMods ?? 2000, deadline, log, emit, shouldStop });
    cursor = res.cursor;
    stats.done = res.done;
    if (!res.done) status = "partial";
    if (opts.mirror !== false && provider.policy === "mirror-if-licensed" && process.env.MODSYNC_MIRROR !== "0") {
      const m = await mirrorPopular(provider, cdn, opts.mirrorLimit ?? Number(process.env.MODSYNC_MIRROR_PER_SLICE ?? 150), deadline + 5 * 60_000);
      stats.mirrored = m.ok; stats.mirrorSkipped = m.skipped; stats.mirrorFailed = m.failed;
    }
  } catch (e) {
    status = "error";
    errorText = (e instanceof Error ? e.message : String(e)).slice(0, 500);
    cursor = prevCursor ? (({ __mode, ...c }) => c)(prevCursor as Record<string, unknown>) : null; // retry the same page next time
  }
  stats.requests = http.requests + cdn.requests;
  stats.retries = http.retries + cdn.retries;
  if (stats.failed > 0 && status === "ok") status = "partial";
  if (stats.failed > 0 && errors.length) errorText = errorText ?? errors.join(" | ").slice(0, 500);
  if (stats.done && mode === "full" && status !== "error") stats.fullAt = new Date().toISOString();

  const finished = status === "error" ? new Date(Date.now() + Math.min(60, 5 * 2 ** 3) * 60_000) : null; // error: retry in <= 40 min
  const cursorOut = cursor ? ({ ...cursor, __mode: mode } as Prisma.InputJsonValue) : Prisma.JsonNull;
  await db.modSyncProvider.update({
    where: { key },
    data: {
      cursor: cursorOut,
      lastRunAt: new Date(),
      lastSuccessAt: status === "error" ? row.lastSuccessAt : new Date(),
      lastStatus: status,
      lastError: errorText,
      lastStats: stats as unknown as Prisma.InputJsonValue,
      // partial (slice budget hit): continue promptly; done: wait the interval; error: back off.
      nextRunAt: status === "partial" && cursor ? new Date(Date.now() + 60_000) : finished ?? new Date(Date.now() + row.intervalMinutes * 60_000),
    },
  });
  await db.modSyncRun.update({ where: { id: run.id }, data: { finishedAt: new Date(), status, stats: stats as unknown as Prisma.InputJsonValue, error: errorText } });
  await db.$executeRaw`delete from "ModSyncRun" where id in (select id from "ModSyncRun" order by "startedAt" desc offset 200)`;
  return stats;
}

/** Mirror the newest release of the most-downloaded redistributable mods that have no local copy yet. */
export async function mirrorPopular(provider: Provider, http: HttpClient, limit: number, deadline: number): Promise<{ ok: number; skipped: number; failed: number }> {
  const sources = provider.key; // GameMod.source == provider key for mirror-eligible providers
  const rows = await db.$queryRaw<{ id: string }[]>`
    select v.id from (
      select distinct on (v."gameModId") v.id, v."gameModId" from "ModVersion" v
      where v."mirrorState" in ('NONE') and v.channel='release' and v."fileUrl" is not null
      order by v."gameModId", v."publishedAt" desc nulls last
    ) v join "GameMod" m on m.id=v."gameModId"
    where m.source=${sources} and m.redistributable and m.active and m."upstreamOk"
    order by coalesce(m.downloads,0) desc limit ${limit}`;
  const out = { ok: 0, skipped: 0, failed: 0 };
  for (const r of rows) {
    if (Date.now() > deadline) break;
    const m = await mirrorVersion(http, r.id);
    if (m.outcome === "FULL") break; // budget reached: stop trying, keep the popular set we have
    if (m.outcome === "OK" || m.outcome === "ALREADY") out.ok++;
    else if (m.outcome === "SKIPPED") out.skipped++;
    else out.failed++;
  }
  return out;
}
