/**
 * Icon/screenshot cache. Downloads an upstream image (https only, size-capped,
 * content-type checked), resizes + converts to WebP with sharp, stores it
 * content-addressed under <mirror>/img/<aa>/<sha256>.webp and returns the key.
 * Served by app/api/nxlabs/img/[key]/route.ts. Only images from the provider
 * CDN of a project we ingest are fetched; every fetch goes through HttpClient.
 */
import { createHash } from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";
import type { HttpClient } from "./http";
import { imagesRoot, mirrorReady } from "./config";

const MAX_SRC_BYTES = 8 * 1024 ** 2;
export const KEY_RE = /^[a-f0-9]{64}$/;

export function imagePath(key: string): string {
  if (!KEY_RE.test(key)) throw new Error("bad image key");
  return path.join(imagesRoot(), key.slice(0, 2), `${key}.webp`);
}

export async function cacheImage(
  http: HttpClient,
  url: string,
  opts: { width: number; height?: number; fit?: "cover" | "inside" } = { width: 128 },
): Promise<string | null> {
  if (!/^https:\/\//i.test(url) || !(await mirrorReady())) return null;
  let buf: Buffer;
  try {
    const res = await http.request(url, { headers: { Accept: "image/*" }, maxRetries: 1, signal: AbortSignal.timeout(15_000) });
    if (!res.ok) return null;
    const len = Number(res.headers.get("content-length") ?? 0);
    if (len > MAX_SRC_BYTES) return null;
    const ab = await res.arrayBuffer();
    if (ab.byteLength > MAX_SRC_BYTES || ab.byteLength === 0) return null;
    buf = Buffer.from(ab);
  } catch {
    return null;
  }
  let out: Buffer;
  try {
    out = await sharp(buf, { limitInputPixels: 40_000_000, animated: false })
      .rotate()
      .resize({ width: opts.width, height: opts.height, fit: opts.fit ?? "inside", withoutEnlargement: true })
      .webp({ quality: 80 })
      .toBuffer();
  } catch {
    return null; // not a decodable image (svg bombs, html error pages, ...)
  }
  const key = createHash("sha256").update(out).digest("hex");
  const p = imagePath(key);
  try {
    try {
      await fs.access(p);
    } catch {
      await fs.mkdir(path.dirname(p), { recursive: true });
      const tmp = `${p}.${process.pid}.tmp`;
      await fs.writeFile(tmp, out);
      await fs.rename(tmp, p);
    }
  } catch {
    return null; // unwritable/full store must never fail the mod upsert
  }
  return key;
}

export const ICON_SIZE = { width: 128, height: 128, fit: "cover" as const };
export const SHOT_SIZE = { width: 960, fit: "inside" as const };
