import fs from "node:fs/promises";
import { KEY_RE, imagePath } from "@/lib/modsync/images";

export const dynamic = "force-dynamic";

/**
 * Serves NX Labs' locally cached mod icons/screenshots (WebP, content-addressed
 * by sha256 so the URL is immutable => cache for a year). No auth: these are
 * public catalog images; the key is validated as 64 hex chars so it can never
 * traverse the filesystem.
 */
export async function GET(_req: Request, { params }: { params: Promise<{ key: string }> }) {
  const { key } = await params;
  if (!KEY_RE.test(key)) return new Response("Not found", { status: 404 });
  try {
    const buf = await fs.readFile(imagePath(key));
    return new Response(new Uint8Array(buf), {
      headers: { "Content-Type": "image/webp", "Cache-Control": "public, max-age=31536000, immutable", "X-Content-Type-Options": "nosniff" },
    });
  } catch {
    return new Response("Not found", { status: 404 });
  }
}
