import type { NormalizedMedia, NormalizedMod } from "./types";

const MEDIA_CAP = 9; // 1 icon + 8 gallery

/** One ordered, de-duplicated, https-only media list for a mod: icon first, then banner/screenshots. */
export function mediaPlan(m: Pick<NormalizedMod, "iconUrl" | "galleryUrls" | "media">): NormalizedMedia[] {
  const out: NormalizedMedia[] = [];
  const seen = new Set<string>();
  const push = (x: NormalizedMedia) => {
    if (!/^https:\/\//i.test(x.url) || x.url.length > 2000 || seen.has(x.url)) return;
    seen.add(x.url);
    out.push(x);
  };
  if (m.iconUrl) push({ kind: "icon", url: m.iconUrl });
  for (const x of m.media ?? []) push(x);
  for (const u of m.galleryUrls ?? []) push({ kind: "screenshot", url: u });
  return out.slice(0, MEDIA_CAP);
}

/** Pull https image URLs out of README markdown/HTML (author-hosted screenshots). Capped, deduped. */
export function imagesFromBody(body: string | null | undefined, cap = 6): string[] {
  if (!body) return [];
  const urls: string[] = [];
  const re = /!\[[^\]]*\]\((https:\/\/[^\s)]+)\)|<img[^>]+src=["'](https:\/\/[^"']+)["']/gi;
  let r: RegExpExecArray | null;
  while ((r = re.exec(body)) && urls.length < cap * 3) {
    const u = (r[1] || r[2]).replace(/&amp;/g, "&");
    // skip badges / shields / tracking pixels
    if (/shields\.io|badge|img\.shields|travis-ci|github\.com\/.*\/workflows|buymeacoffee|ko-fi\.com\/img|\.svg(\?|$)/i.test(u)) continue;
    if (!urls.includes(u)) urls.push(u);
  }
  return urls.slice(0, cap);
}
E
