import type { NormalizedMod } from "./types";

export function normName(s: string | null | undefined): string {
  return (s ?? "").toLowerCase().replace(/[\s_\-.]+/g, "").replace(/[^a-z0-9]/g, "");
}

export function githubRepo(url: string | null | undefined): string | null {
  const m = /github\.com\/([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+?)(?:\.git)?(?:[/#?]|$)/i.exec(url ?? "");
  return m ? `${m[1]}/${m[2]}`.toLowerCase() : null;
}

/**
 * Identity key used by the cross-provider dedupe pass: normalised project name + normalised
 * primary author. Two rows with the same key in the same family but different sources are the
 * same project published on several providers. (lib/modsync/dedupe.ts also joins on GitHub repo.)
 */
export function dedupeKeyFor(m: Pick<NormalizedMod, "name" | "authorName">): string | null {
  const n = normName(m.name);
  const a = normName(m.authorName);
  return n.length >= 3 && a ? `${n}|${a}` : null;
}
