 * Modrinth AND Hangar AND Spigot; a mod on Thunderstore AND GitHub). We keep every row (installers
 * and the verifier still address them by source/sourceId) but link them:
 *
 *   GameMod.duplicateOfId = id of the CANONICAL row   (null on the canonical/unique row)
 *   GameMod.dedupeKey     = the identity key the group was joined on
 *
 * Grouping (same gameFamily, DIFFERENT sources only — two rows of one provider are never merged):
 *   A. same normalised name AND same normalised primary author, or
 *   B. same GitHub repo (sourceUrl) AND same normalised name.
 *
 * Canonical choice (documented in docs/MODS-SOURCES.md): the row whose provider is best for the
 * customer: 1) can be mirrored/installed from our own store (redistributable + a direct file),
 * 2) provider rank (SOURCE_RANK below: first-party-API providers with licence data first),
 * 3) richer metadata (long description, versions), 4) more downloads. Customer listings hide rows
 * with duplicateOfId != null; /admin keeps showing them.
 */
import { db } from "../db";
import { githubRepo, normName } from "./dedupe-key";

export const SOURCE_RANK = ["modrinth", "hangar", "thunderstore", "umod", "ficsit", "factorio_portal", "vintagestory_moddb", "curseforge", "spigotmc", "mod_io", "steam_workshop", "reforger_workshop", "github", "nexus", "codefling", "manual"];
const rank = (s: string) => { const i = SOURCE_RANK.indexOf(s); return i < 0 ? 99 : i; };

export interface DedupeRow {
  id: string; gameFamily: string; source: string; name: string; authorName: string | null; sourceUrl: string | null;
  downloads: number | null; redistributable: boolean; hasBody: boolean; versionCount: number; active: boolean;
}

export interface DedupeGroup { family: string; canonical: string; duplicates: string[]; key: string }

class UF {
  p = new Map<string, string>();
  find(x: string): string { let r = this.p.get(x) ?? x; if (r !== x) { r = this.find(r); this.p.set(x, r); } return r; }
  union(a: string, b: string) { const ra = this.find(a), rb = this.find(b); if (ra !== rb) this.p.set(ra, rb); }
}

export function pickCanonical(rows: DedupeRow[]): DedupeRow {
  const score = (r: DedupeRow) => [r.redistributable && r.versionCount > 0 ? 0 : 1, rank(r.source), r.hasBody ? 0 : 1, -(r.versionCount > 0 ? 1 : 0), -(r.downloads ?? 0)];
  return [...rows].sort((a, b) => { const sa = score(a), sb = score(b); for (let i = 0; i < sa.length; i++) if (sa[i] !== sb[i]) return sa[i] - sb[i]; return a.id < b.id ? -1 : 1; })[0];
}

/** Pure grouping step (unit-tested). */
export function groupDuplicates(rows: DedupeRow[]): DedupeGroup[] {
  const byFam = new Map<string, DedupeRow[]>();
  for (const r of rows) (byFam.get(r.gameFamily) ?? byFam.set(r.gameFamily, []).get(r.gameFamily)!).push(r);
  const out: DedupeGroup[] = [];
  for (const [family, list] of byFam) {
    const uf = new UF();
    const keyA = new Map<string, DedupeRow[]>();
    const keyB = new Map<string, DedupeRow[]>();
    for (const r of list) {
      const n = normName(r.name);
      if (n.length < 3) continue;
      const a = normName(r.authorName);
      if (a) { const k = `${n}|${a}`; (keyA.get(k) ?? keyA.set(k, []).get(k)!).push(r); }
      const g = githubRepo(r.sourceUrl);
      if (g) { const k = `${g}|${n}`; (keyB.get(k) ?? keyB.set(k, []).get(k)!).push(r); }
    }
    for (const m of [keyA, keyB]) for (const rs of m.values()) if (new Set(rs.map((x) => x.source)).size > 1) for (const r of rs) uf.union(rs[0].id, r.id);
    const comps = new Map<string, DedupeRow[]>();
    const touched = new Set([...keyA.values(), ...keyB.values()].flat().map((r) => r.id));
    for (const r of list) if (touched.has(r.id)) (comps.get(uf.find(r.id)) ?? comps.set(uf.find(r.id), []).get(uf.find(r.id))!).push(r);
    for (const rs of comps.values()) {
      if (rs.length < 2 || new Set(rs.map((x) => x.source)).size < 2) continue;
      // Within one source keep each row canonical-less: only the best row per OTHER source is linked.
      const canon = pickCanonical(rs);
      const dups = rs.filter((r) => r.id !== canon.id && r.source !== canon.source).map((r) => r.id);
      if (dups.length) out.push({ family, canonical: canon.id, duplicates: dups, key: `${normName(canon.name)}|${normName(canon.authorName)}` });
    }
  }
  return out;
}

export async function loadDedupeRows(family?: string): Promise<DedupeRow[]> {
  const rows = await db.$queryRaw<(Omit<DedupeRow, "hasBody" | "versionCount" | "downloads"> & { downloads: number | null; hasBody: boolean; versionCount: bigint })[]>`
    select m.id, m."gameFamily", m.source, m.name, m."authorName", m."sourceUrl", m.downloads, m.redistributable, m.active,
           (m."longDescription" is not null) as "hasBody",
           (select count(*) from "ModVersion" v where v."gameModId" = m.id) as "versionCount"
    from "GameMod" m
    where m."upstreamOk" ${family ? db.$queryRaw`and m."gameFamily" = ${family}`.then ? undefined : undefined : undefined}`;
  return rows.map((r) => ({ ...r, versionCount: Number(r.versionCount) }));
}

/** Apply the pass idempotently: resets previous links for the family first, then re-links. */
export async function runDedupe(opts: { family?: string; dryRun?: boolean } = {}): Promise<{ groups: number; linked: number; sample: DedupeGroup[] }> {
  const all = await loadDedupeRows();
  const rows = opts.family ? all.filter((r) => r.gameFamily === opts.family) : all;
  const groups = groupDuplicates(rows);
  if (!opts.dryRun) {
    await db.gameMod.updateMany({ where: { duplicateOfId: { not: null }, ...(opts.family ? { gameFamily: opts.family } : {}) }, data: { duplicateOfId: null } });
    for (const g of groups) {
      await db.gameMod.updateMany({ where: { id: { in: g.duplicates } }, data: { duplicateOfId: g.canonical, dedupeKey: g.key } });
      await db.gameMod.update({ where: { id: g.canonical }, data: { dedupeKey: g.key } });
    }
  }
  return { groups: groups.length, linked: groups.reduce((n, g) => n + g.duplicates.length, 0), sample: groups.slice(0, 5) };
}
