 * Minimal streaming reader for a top-level JSON ARRAY of objects (Thunderstore's per-community
 * package list is one ~170 MB array — never `res.json()` it). Yields each element as parsed JSON
 * while holding only the current element in memory.
 */
export async function* streamJsonArray<T = unknown>(source: AsyncIterable<Uint8Array | string>): AsyncGenerator<T> {
  const dec = new TextDecoder("utf-8");
  let buf = "";
  let depth = 0;
  let inStr = false;
  let esc = false;
  let start = -1;
  let scanned = 0;
  const feed = async function* (chunk: string): AsyncGenerator<T> {
    buf += chunk;
    for (let i = scanned; i < buf.length; i++) {
      const c = buf.charCodeAt(i);
      if (inStr) {
        if (esc) esc = false;
        else if (c === 92) esc = true;
        else if (c === 34) inStr = false;
        continue;
      }
      if (c === 34) { inStr = true; continue; }
      if (c === 91 || c === 123) { // [ {
        if (depth === 1 && c === 123) start = i;
        depth++;
      } else if (c === 93 || c === 125) { // ] }
        depth--;
        if (depth === 1 && c === 125 && start >= 0) {
          yield JSON.parse(buf.slice(start, i + 1)) as T;
          buf = buf.slice(i + 1);
          i = -1;
          start = -1;
        }
      }
    }
    // drop already-scanned prefix that is not part of a pending element
    if (start < 0) { buf = ""; scanned = 0; } else scanned = buf.length;
  };
  for await (const chunk of source) {
    yield* feed(typeof chunk === "string" ? chunk : dec.decode(chunk, { stream: true }));
  }
  yield* feed(dec.decode());
}
