/**
 * Thunderstore — every community that maps to a game we host. Public v1 package list
 * (https://thunderstore.io/c/<community>/api/v1/package/): ONE huge array per community (Valheim
 * ~170 MB) with every version embedded. We never `res.json()` it: the body is downloaded once to a
 * disk cache (If-Modified-Since / ETag honoured, 12 h freshness) and STREAM-parsed.
 *
 * Per new/changed package we add the experimental per-version README + changelog endpoints (one
 * request each, paced) so the preview page has a real long description + changelog.
 *
 * Licence/ToS: Thunderstore has no licence field and no published API ToS; packages are all-rights-
 * reserved by default => METADATA + LINK-THROUGH only, never mirrored (policy metadata-only).
 * Screenshots: the API exposes none; we surface author-hosted images found in the README
 * (hotlink-proxied, never stored).
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import { HttpError } from "../http";
import { mirrorReady, tmpRoot } from "../config";
import { imagesFromBody } from "../media";
import { streamJsonArray } from "../json-stream";
import type { NormalizedDep, NormalizedMod, NormalizedVersion, Provider, SliceResult, SyncContext } from "../types";

export const TS_COMMUNITIES: { id: string; family: string }[] = [
  { id: "valheim", family: "valheim" },
  { id: "palworld", family: "palworld" },
  { id: "v-rising", family: "vrising" },
  { id: "core-keeper", family: "corekeeper" },
  { id: "sons-of-the-forest", family: "sonsoftheforest" },
  { id: "schedule-i", family: "schedule1" },
  { id: "sunkenland", family: "sunkenland" },
];

export interface TsVersion {
  name?: string; full_name?: string; description?: string | null; icon?: string | null; version_number: string;
  dependencies?: string[]; download_url?: string; downloads?: number; date_created?: string; website_url?: string | null;
  is_active?: boolean; uuid4?: string; file_size?: number;
}
export interface TsPackage {
  name: string; full_name: string; owner: string; package_url: string; date_created?: string; date_updated?: string;
  uuid4?: string; rating_score?: number; is_pinned?: boolean; is_deprecated?: boolean; has_nsfw_content?: boolean;
  categories?: string[]; versions?: TsVersion[];
}

const CATEGORY_RULES: [string, string][] = [["Modpacks", "Modpacks"], ["Libraries", "Core"], ["Tweaks", "Tweaks"], ["Building", "Building"], ["Tools", "Admin"]];
export const tsCategory = (cats: string[]) => CATEGORY_RULES.find(([raw]) => cats.includes(raw))?.[1] ?? "Content";

export function latestTsVersion(p: TsPackage): TsVersion | null {
  const vs = p.versions ?? [];
  return vs.length ? vs.reduce((a, b) => (new Date(b.date_created ?? 0) > new Date(a.date_created ?? 0) ? b : a)) : null;
}

/** "Owner-Name-1.2.3" -> dependency (Thunderstore dependency strings always end in a semver). */
export function parseTsDep(s: string): NormalizedDep | null {
  const m = /^(.+)-(\d+\.\d+\.\d+)$/.exec(s);
  return m ? { kind: "required", source: "thunderstore", projectId: m[1], name: m[1].split("-").slice(1).join("-"), versionId: m[2] } : null;
}

/** Quality gate shared with the legacy importer: deprecated, NSFW and client-only packages are not offered. */
export function tsExcluded(p: TsPackage): string | null {
  const c = p.categories ?? [];
  if (p.is_deprecated) return "deprecated";
  if (p.has_nsfw_content) return "nsfw";
  if (c.includes("Client-side") && !c.includes("Server-side")) return "client-only";
  if (!latestTsVersion(p)) return "no-version";
  return null;
}

/**
 * Side-requirement HEURISTIC (Thunderstore has no real flag, only community tags): a "Server-side"
 * tag means it loads on a dedicated server; "Client-side" too => both ends optional; no tag => unknown.
 */
export function tsSides(cats: string[]): { clientSide: string | null; serverSide: string | null } {
  const c = cats.includes("Client-side"), s = cats.includes("Server-side");
  if (s && c) return { clientSide: "optional", serverSide: "optional" };
  if (s) return { clientSide: "optional", serverSide: "required" };
  return { clientSide: null, serverSide: null };
}

const GH = /^https:\/\/github\.com\/[^/]+\/[^/]+/i;

export function parseTsPackage(p: TsPackage, family: string, readme?: string | null, changelog?: string | null, communityLabel = "thunderstore"): NormalizedMod {
  const latest = latestTsVersion(p)!;
  const cats = p.categories ?? [];
  const sides = tsSides(cats);
  const sorted = [...(p.versions ?? [])].sort((a, b) => +new Date(b.date_created ?? 0) - +new Date(a.date_created ?? 0));
  const web = latest.website_url?.trim() || null;
  const created = (p.versions ?? []).map((v) => +new Date(v.date_created ?? 0)).filter((n) => n > 0);
  const versions: NormalizedVersion[] = sorted.slice(0, 25).map((v, i) => ({
    versionId: v.version_number,
    versionNumber: v.version_number,
    channel: "release",
    gameVersions: [],
    loaders: ["bepinex"],
    fileName: `${p.full_name}-${v.version_number}.zip`,
    fileUrl: v.download_url ?? null,
    fileBytes: v.file_size ?? null,
    downloads: v.downloads ?? null,
    changelog: i === 0 ? changelog || null : null,
    deps: (v.dependencies ?? []).map(parseTsDep).filter((d): d is NormalizedDep => !!d),
    dependencies: v.dependencies ?? [],
    clientSide: sides.clientSide,
    serverSideReq: sides.serverSide,
    publishedAt: v.date_created ? new Date(v.date_created) : null,
  }));
  const shots = imagesFromBody(readme);
  return {
    gameFamily: family,
    source: communityLabel,
    sourceId: p.full_name,
    slugHint: p.full_name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80) || "mod",
    name: p.name.replace(/_/g, " ").trim() || p.name,
    category: tsCategory(cats),
    description: latest.description || null,
    body: readme || null,
    bodyFormat: "markdown",
    url: p.package_url,
    sourceUrl: web && GH.test(web) ? web : null,
    websiteUrl: web && !GH.test(web) ? web : null,
    iconUrl: latest.icon || null,
    media: shots.map((u) => ({ kind: "screenshot" as const, url: u })),
    authorName: p.owner,
    authors: [{ name: p.owner, url: `https://thunderstore.io/c/${family}/p/${p.owner}/` }],
    license: null, // Thunderstore publishes none; never fabricate one
    downloads: (p.versions ?? []).reduce((n, v) => n + (v.downloads ?? 0), 0) || null,
    followers: p.rating_score ?? null, // = likes on Thunderstore, not a 0-5 rating
    categories: cats,
    tags: cats.map((c) => c.toLowerCase()),
    loaders: ["bepinex"],
    serverSide: sides.serverSide,
    clientSide: sides.clientSide,
    appliesToVariant: "bepinex",
    firstPublishedAt: created.length ? new Date(Math.min(...created)) : p.date_created ? new Date(p.date_created) : null,
    upstreamUpdatedAt: p.date_updated ? new Date(p.date_updated) : new Date(+new Date(latest.date_created ?? 0) || Date.now()),
    versions,
  };
}

async function cachePath(community: string): Promise<string> {
  const dir = (await mirrorReady()) ? path.join(tmpRoot(), "thunderstore") : path.join(os.tmpdir(), "nxlabs-thunderstore");
  await fs.promises.mkdir(dir, { recursive: true });
  return path.join(dir, `${community}.json`);
}

/** Download the community dump to disk (conditional on the previous copy) and return its path. */
async function ensureDump(ctx: SyncContext, community: string): Promise<{ file: string; fresh: boolean }> {
  const file = await cachePath(community);
  const metaFile = `${file}.meta`;
  let meta: { etag?: string | null; lastModified?: string | null; at?: number } = {};
  try { meta = JSON.parse(await fs.promises.readFile(metaFile, "utf8")); } catch {}
  const have = fs.existsSync(file);
  if (have && meta.at && Date.now() - meta.at < 12 * 3600_000) return { file, fresh: false };
  const url = `https://thunderstore.io/c/${community}/api/v1/package/`;
  const res = await ctx.http.request(url, { cond: have ? { etag: meta.etag, lastModified: meta.lastModified } : undefined, headers: { "Accept-Encoding": "gzip" } });
  if (res.status === 304) {
    await fs.promises.writeFile(metaFile, JSON.stringify({ ...meta, at: Date.now() }));
    return { file, fresh: false };
  }
  if (!res.ok || !res.body) throw new HttpError(res.status, url);
  const tmp = `${file}.${process.pid}.part`;
  await pipeline(Readable.fromWeb(res.body as never), fs.createWriteStream(tmp));
  await fs.promises.rename(tmp, file);
  await fs.promises.writeFile(metaFile, JSON.stringify({ etag: res.headers.get("etag"), lastModified: res.headers.get("last-modified"), at: Date.now() }));
  ctx.log(`thunderstore ${community}: dump downloaded (${(fs.statSync(file).size / 1e6).toFixed(0)} MB)`);
  return { file, fresh: true };
}

async function text(ctx: SyncContext, url: string): Promise<string | null> {
  try {
    const res = await ctx.http.request(url, { maxRetries: 2 });
    if (!res.ok) return null;
    const j = (await res.json()) as { markdown?: string | null };
    return j.markdown?.trim() || null;
  } catch {
    return null;
  }
}

export const thunderstore: Provider = {
  key: "thunderstore",
  label: "Thunderstore",
  games: TS_COMMUNITIES.map((c) => c.family),
  ratePerMin: Number(process.env.MODSYNC_THUNDERSTORE_RATE ?? 150),
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "metadata-only",
  async run(ctx: SyncContext): Promise<SliceResult> {
    let ci = Number(ctx.cursor?.community ?? 0);
    const only = process.env.MODSYNC_THUNDERSTORE_ONLY?.split(",").filter(Boolean);
    const communities = only?.length ? TS_COMMUNITIES.filter((c) => only.includes(c.id)) : TS_COMMUNITIES;
    let produced = 0;
    for (; ci < communities.length; ci++) {
      const { id, family } = communities[ci];
      const { file } = await ensureDump(ctx, id);
      let batch: TsPackage[] = [];
      const stats = { raw: 0, excluded: 0, unchanged: 0, emitted: 0 };
      let interrupted = false;
      const flush = async () => {
        if (!batch.length) return;
        const known = await ctx.known("thunderstore", batch.map((b) => b.full_name));
        const mods: NormalizedMod[] = [];
        for (const p of batch) {
          const k = known.get(p.full_name);
          const upd = p.date_updated ? new Date(p.date_updated) : null;
          if (k && k.hasBody && k.upstreamUpdatedAt && upd && +k.upstreamUpdatedAt >= +upd && k.versionCount > 0) { stats.unchanged++; continue; }
          if (produced + mods.length >= ctx.maxMods || Date.now() > ctx.deadline) { interrupted = true; break; }
          const latest = latestTsVersion(p)!;
          const base = `https://thunderstore.io/api/experimental/package/${encodeURIComponent(p.owner)}/${encodeURIComponent(p.name)}/${encodeURIComponent(latest.version_number)}`;
          const [readme, changelog] = await Promise.all([text(ctx, `${base}/readme/`), text(ctx, `${base}/changelog/`)]);
          mods.push(parseTsPackage(p, family, readme, changelog));
        }
        if (mods.length) { await ctx.emit(mods); produced += mods.length; stats.emitted += mods.length; }
        batch = [];
      };
      for await (const p of streamJsonArray<TsPackage>(fs.createReadStream(file))) {
        stats.raw++;
        if (tsExcluded(p)) { stats.excluded++; continue; }
        batch.push(p);
        if (batch.length >= 40) {
          await flush();
          if (interrupted || (await ctx.shouldStop())) break;
        }
      }
      if (!interrupted) await flush();
      ctx.log(`thunderstore ${id}: ${JSON.stringify(stats)}`);
      if (interrupted || (await ctx.shouldStop())) return { cursor: { community: ci }, done: false };
    }
    return { cursor: null, done: true };
  },
};
E

