/**
 * SpigotMC plugins via Spiget (https://spiget.org, the public community API mirror — SpigotMC itself
 * blocks bots and has no API). Free resources only: `premium` resources are skipped, resources hosted
 * externally keep their external link. Metadata + link-through: SpigotMC resources are author-licensed
 * (most "all rights reserved"), so files are NEVER mirrored (policy metadata-only).
 * Fields: tag -> short summary, base64 HTML description, rating, downloads, tested versions, links
 * (source/donation/discord/wiki), per-version release dates + latest update changelog.
 */
import type { NormalizedMod, NormalizedVersion, Provider, SliceResult, SyncContext } from "../types";

const API = "https://api.spiget.org/v2";
const SPIGOT = "https://www.spigotmc.org/";
const PAGE = 100;
const FIELDS = "id,name,tag,description,sourceCodeLink,donationLink,updateDate,releaseDate,premium,downloads,likes,rating,author,category,icon,file,testedVersions,version,links,external,existenceStatus";

export interface SpResource {
  id: number; name: string; tag?: string; description?: string; sourceCodeLink?: string; donationLink?: string;
  updateDate?: number; releaseDate?: number; premium?: boolean; downloads?: number; likes?: number;
  rating?: { count?: number; average?: number }; author?: { id: number }; category?: { id: number };
  icon?: { url?: string }; file?: { type?: string; size?: number; sizeUnit?: string; url?: string; externalUrl?: string };
  testedVersions?: string[]; version?: { id: number }; links?: Record<string, string>; external?: boolean;
}
export interface SpVersion { id: number; name: string; releaseDate: number; downloads?: number }
export interface SpUpdate { id: number; title?: string; description?: string; date?: number }

export const b64 = (s: string | undefined | null) => (s ? Buffer.from(s, "base64").toString("utf8") : "");
const lbl = (s: string) => { try { return Buffer.from(s, "base64").toString("utf8"); } catch { return s; } };

const CAT: Record<number, string> = { 4: "Plugins", 5: "Plugins", 6: "Plugins", 7: "Admin", 8: "Plugins", 9: "Core", 12: "Admin", 15: "Admin", 17: "Fun", 18: "Plugins", 19: "Plugins", 21: "Plugins", 22: "Plugins", 23: "Economy", 24: "Plugins", 26: "Core", 29: "Plugins" };

/** Spiget `links` keys are base64 of the human label for custom links, plain words for built-ins. */
export function spLinks(links: Record<string, string> | undefined): { discord?: string; wiki?: string; donation?: string; website?: string; issues?: string } {
  const out: { discord?: string; wiki?: string; donation?: string; website?: string; issues?: string } = {};
  for (const [k, raw] of Object.entries(links ?? {})) {
    if (!/^https?:\/\//i.test(raw)) continue;
    const label = (/^[A-Za-z]+$/.test(k) ? k : lbl(k)).toLowerCase();
    if (/discord/.test(label) || /discord\.(gg|com)/.test(raw)) out.discord ??= raw;
    else if (/wiki|docs|documentation|guide/.test(label)) out.wiki ??= raw;
    else if (/donat|patreon|ko-fi|paypal/.test(label)) out.donation ??= raw;
    else if (/issue|bug|support/.test(label)) out.issues ??= raw;
    else if (/additionalinformation|website|home/.test(label)) out.website ??= raw;
  }
  return out;
}

export function parseSpigotResource(r: SpResource, authorName: string | null, authorAvatar: string | null, versions: SpVersion[], updates: SpUpdate[], category?: string | null): NormalizedMod {
  const links = spLinks(r.links);
  const ext = r.file?.externalUrl ?? null;
  const vs: NormalizedVersion[] = versions.slice(0, 25).map((v, i) => {
    const upd = i === 0 ? updates[0] : updates.find((u) => u.date && Math.abs(u.date - v.releaseDate) < 120);
    return {
      versionId: String(v.id),
      versionNumber: v.name,
      channel: "release",
      gameVersions: i === 0 ? r.testedVersions ?? [] : [],
      loaders: ["spigot", "paper"],
      fileUrl: null, // SpigotMC downloads need a browser session; link-through only
      downloads: v.downloads ?? null,
      changelog: upd ? [upd.title, b64(upd.description)].filter(Boolean).join("\n\n") || null : null,
      publishedAt: v.releaseDate ? new Date(v.releaseDate * 1000) : null,
      serverSideReq: "required",
    };
  });
