  return {
    gameFamily: "minecraft",
    source: "spigotmc",
    sourceId: String(r.id),
    slugHint: `${r.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "")}-${r.id}`.slice(0, 80),
    name: r.name,
    category: (r.category && CAT[r.category.id]) || category || "Plugins",
    description: r.tag || null,
    body: b64(r.description) || null,
    bodyFormat: "html",
    url: `https://www.spigotmc.org/resources/${r.id}/`,
    sourceUrl: r.sourceCodeLink || null,
    websiteUrl: ext && !/github\.com/.test(ext) ? ext : links.website ?? null,
    discordUrl: links.discord ?? null,
    wikiUrl: links.wiki ?? null,
    issuesUrl: links.issues ?? null,
    donationUrl: r.donationLink || links.donation || null,
    iconUrl: icon,
    authorName,
    authorAvatarUrl: authorAvatar,
    authors: authorName ? [{ name: authorName, url: r.author ? `https://www.spigotmc.org/members/${r.author.id}/` : null, avatarUrl: authorAvatar }] : undefined,
    license: null,
    downloads: r.downloads ?? null,
    followers: r.likes ?? null,
    rating: r.rating?.average && r.rating.count ? r.rating.average : null,
    ratingCount: r.rating?.count ?? null,
    categories: category ? [category] : [],
    tags: [],
    gameVersions: r.testedVersions ?? [],
    loaders: ["spigot", "paper"],
    serverSide: "required",
    clientSide: "unsupported",
    appliesToVariant: "paper",
    paid: !!r.premium,
    firstPublishedAt: r.releaseDate ? new Date(r.releaseDate * 1000) : null,
    upstreamUpdatedAt: r.updateDate ? new Date(r.updateDate * 1000) : null,
    versions: vs,
  };
}

export const spigotmc: Provider = {
  key: "spigotmc",
  label: "SpigotMC (via Spiget)",
  games: ["minecraft"],
  ratePerMin: Number(process.env.MODSYNC_SPIGET_RATE ?? 90),
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "metadata-only",
  async run(ctx: SyncContext): Promise<SliceResult> {
    let page = Number(ctx.cursor?.page ?? 1);
    const maxPages = Number(process.env.MODSYNC_SPIGET_MAX_PAGES ?? 150); // top ~15k by downloads
    const authors = new Map<number, { name: string | null; avatar: string | null }>();
    const cats = new Map<number, string>();
    try {
      const cs = await ctx.http.json<{ id: number; name: string }[]>(`${API}/categories?size=100&fields=id,name`);
      for (const c of cs) cats.set(c.id, c.name);
    } catch {}
    let produced = 0;
    while (true) {
      if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { page }, done: false };
      const sort = ctx.mode === "recent" ? "-updateDate" : "-downloads";
      const list = await ctx.http.json<SpResource[]>(`${API}/resources?size=${PAGE}&page=${page}&sort=${sort}&fields=${FIELDS}`);
      if (!list.length) return { cursor: null, done: true };
      const known = await ctx.known("spigotmc", list.map((r) => String(r.id)));
      const mods: NormalizedMod[] = [];
      for (const r of list) {
        if (r.premium) continue;
        const k = known.get(String(r.id));
        const upd = r.updateDate ? new Date(r.updateDate * 1000) : null;
        if (k && k.hasBody && k.versionCount > 0 && k.upstreamUpdatedAt && upd && +k.upstreamUpdatedAt >= +upd) continue;
        try {
          const detail = await ctx.http.json<SpResource>(`${API}/resources/${r.id}?fields=description`);
          const a = r.author?.id;
          if (a && !authors.has(a)) {
            try {
              const au = await ctx.http.json<{ name?: string; icon?: { url?: string } }>(`${API}/authors/${a}?fields=name,icon.url`);
              authors.set(a, { name: au.name ?? null, avatar: au.icon?.url ?? null });
            } catch { authors.set(a, { name: null, avatar: null }); }
          }
          const [versions, updates] = await Promise.all([
            ctx.http.json<SpVersion[]>(`${API}/resources/${r.id}/versions?size=10&sort=-releaseDate&fields=id,name,releaseDate,downloads`).catch(() => [] as SpVersion[]),
            ctx.http.json<SpUpdate[]>(`${API}/resources/${r.id}/updates?size=10&sort=-date&fields=id,title,description,date`).catch(() => [] as SpUpdate[]),
          ]);
          const au = a ? authors.get(a) : undefined;
          mods.push(parseSpigotResource({ ...r, description: detail.description }, au?.name ?? null, au?.avatar ?? null, versions, updates, r.category ? cats.get(r.category.id) ?? null : null));
        } catch (e) {
          ctx.log(`spigotmc ${r.id} failed: ${e instanceof Error ? e.message : e}`);
        }
      }
      if (mods.length) { await ctx.emit(mods); produced += mods.length; }
      ctx.log(`spigotmc page=${page} +${mods.length}`);
      page++;
      if (page > maxPages || list.length < PAGE) return { cursor: null, done: true };
      if (ctx.mode === "recent" && page > 10) return { cursor: null, done: true };
    }
  },
};
