  const versions: string[] = [], loaders: string[] = [];
  for (const x of gv ?? []) (/^\d/.test(x) ? versions : LOADER_NAMES.has(x.toLowerCase()) ? loaders : []).push(x.toLowerCase() === x ? x : LOADER_NAMES.has(x.toLowerCase()) ? x.toLowerCase() : x);
  return { versions, loaders };
}

export function parseCfFile(f: CfFile, allowDist: boolean): NormalizedVersion {
  const { versions, loaders } = splitCfGameVersions(f.gameVersions);
  const deps: NormalizedDep[] = (f.dependencies ?? []).filter((d) => REL[d.relationType]).map((d) => ({ kind: REL[d.relationType], source: "curseforge", projectId: String(d.modId) }));
  return {
    versionId: String(f.id),
    versionNumber: (f.displayName || f.fileName).slice(0, 120),
    channel: f.releaseType === 1 ? "release" : f.releaseType === 2 ? "beta" : "alpha",
    gameVersions: versions,
    loaders,
    fileName: f.fileName,
    fileUrl: allowDist ? f.downloadUrl ?? null : null,
    fileBytes: f.fileLength ?? null,
    sha1: f.hashes?.find((h) => h.algo === 1)?.value ?? null,
    downloads: f.downloadCount ?? null,
    deps,
    dependencies: f.dependencies ?? [],
    publishedAt: f.fileDate ? new Date(f.fileDate) : null,
  };
}

export function parseCfMod(m: CfMod, family: string, descriptionHtml?: string | null, changelogHtml?: string | null): NormalizedMod {
  const cls = family === "minecraft" ? MC_CLASSES[m.classId ?? 6] : undefined;
  const allow = m.allowModDistribution !== false;
  const files = [...(m.latestFiles ?? [])].sort((a, b) => +new Date(b.fileDate) - +new Date(a.fileDate));
  const versions = files.map((f) => parseCfFile(f, allow));
  if (versions[0] && changelogHtml) versions[0].changelog = changelogHtml;
  const allVer = [...new Set(versions.flatMap((v) => v.gameVersions))];
  const allLoad = [...new Set([...(cls?.loaders ?? []), ...versions.flatMap((v) => v.loaders)])];
  const l = m.links ?? {};
  return {
    gameFamily: family,
    source: "curseforge",
    sourceId: String(m.id),
    slugHint: m.slug,
    name: m.name,
    category: cls?.category ?? "Mods",
    description: m.summary || null,
    body: descriptionHtml || null,
    bodyFormat: "html",
    url: `https://www.curseforge.com/${family === "minecraft" ? "minecraft" : family}/${cls ? ({ 6: "mc-mods", 5: "bukkit-plugins", 4471: "modpacks", 12: "texture-packs", 6945: "data-packs", 6552: "shaders" } as Record<number, string>)[m.classId ?? 6] : "mods"}/${m.slug}`,
    sourceUrl: l.sourceUrl || null,
    websiteUrl: l.websiteUrl || null,
    issuesUrl: l.issuesUrl || null,
    wikiUrl: l.wikiUrl || null,
    iconUrl: m.logo?.thumbnailUrl || m.logo?.url || null,
    media: (m.screenshots ?? []).map((s) => ({ kind: "screenshot" as const, url: s.url, title: s.title || null, description: s.description || null })),
    authorName: m.authors?.[0]?.name ?? null,
    authors: (m.authors ?? []).map((a) => ({ name: a.name, url: a.url ?? null })),
    license: null, // CurseForge exposes no licence; allowModDistribution is a permission flag, not a licence
    downloads: m.downloadCount ?? null,
    followers: m.thumbsUpCount ?? null,
    categories: (m.categories ?? []).map((c) => c.name),
    tags: (m.categories ?? []).map((c) => c.name.toLowerCase()),
    gameVersions: allVer,
    loaders: allLoad,
    appliesToVariant: cls?.variant ?? null,
    firstPublishedAt: m.dateCreated ? new Date(m.dateCreated) : null,
    upstreamUpdatedAt: m.dateModified ? new Date(m.dateModified) : null,
    versions,
  };
}

