const TAG_CATEGORY_RULES: Array<[RegExp, string]> = [
  [/rebalanc|gameplay|game.?mode/i, "Balance"],
  [/structure|building/i, "Building"],
  [/creature|npc/i, "Content"],
  [/visual|sound|ui/i, "QoL"],
