/**
 * Steam Workshop via the official Steam Web API (IPublishedFileService/QueryFiles). Needs
 * STEAM_WEB_API_KEY (skipped with an admin message when absent).
 *
 * Policy: METADATA + LINK-THROUGH ONLY. Workshop items belong to their authors under the Steam
 * Workshop EULA; files are NEVER downloaded or mirrored by this provider (policy metadata-only —
 * the runner never offers it to the mirror). Dedicated servers fetch items themselves via
 * `steamcmd workshop_download_item` / the game's own WorkshopItems mechanism.
 * Steam has no per-item version history or licence: we record one pseudo-version per item
 * (versionNumber = last-updated date) and licence = null (never invented).
 * Rate: ≤ 60 req/min (Steam's published ceiling is 100 000/day per key).
 */
import type { NormalizedDep, NormalizedMod, Provider, SliceResult, SyncContext } from "../types";

const API = "https://api.steampowered.com";
const PAGE = 100;

/** Real CLIENT appids (Workshop items live under the client appid) — mirrors scripts/import-steamworkshop-catalog.ts. */
export const STEAM_APPIDS: Record<string, number> = {
  ark: 346110, unturned: 304930, dst: 322330, squad: 393380, empyrion: 383120, soulmask: 2646460, projectzomboid: 108600,
  tf2: 440, l4d2: 550, palworld: 1623730, gmod: 4000, spaceengineers: 244850, barotrauma: 602960, stationeers: 544550,
  kf2: 232090, necesse: 1169040, conan: 440900, cs2: 730, dayz: 221100,
};

export interface WsFile {
  result: number; publishedfileid: string; creator?: string; title?: string; file_description?: string; preview_url?: string;
  file_size?: string | number; subscriptions?: number; lifetime_subscriptions?: number; favorited?: number; views?: number;
  banned?: boolean; visibility?: number; time_created?: number; time_updated?: number;
  tags?: { tag: string; display_name?: string }[]; previews?: { url?: string; preview_type?: number; sortorder?: number }[];
  children?: { publishedfileid: string }[]; vote_data?: { score?: number; votes_up?: number; votes_down?: number };
}
export interface WsPlayer { steamid: string; personaname?: string; avatarfull?: string; profileurl?: string }

const TAG_RULES: [RegExp, string][] = [[/rebalanc|gameplay|game.?mode/i, "Balance"], [/structure|building/i, "Building"], [/creature|npc/i, "Content"], [/visual|sound|ui/i, "QoL"], [/map|environment/i, "Maps"]];
const categoryForTags = (tags: WsFile["tags"]) => { for (const t of tags ?? []) for (const [re, c] of TAG_RULES) if (re.test(t.display_name ?? t.tag)) return c; return "Workshop"; };
const kebab = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "workshop-item";
const plain = (s: string) => s.replace(/\[\/?[a-z0-9=*"'\s:./-]*?\]/gi, " ").replace(/\s+/g, " ").trim();
export function shortFrom(s: string | undefined, max = 200): string | null {
  const t = plain(s ?? "");
  if (!t) return null;
  if (t.length <= max) return t;
  const cut = t.slice(0, max); const sp = cut.lastIndexOf(" ");
  return `${cut.slice(0, sp > 100 ? sp : max)}…`;
}

export function parseWorkshopItem(f: WsFile, family: string, author?: WsPlayer): NormalizedMod {
  const id = f.publishedfileid;
  const shots = (f.previews ?? []).filter((p) => (p.preview_type ?? 0) === 0 && p.url).sort((a, b) => (a.sortorder ?? 0) - (b.sortorder ?? 0)).map((p) => p.url!);
  const upd = f.time_updated ? new Date(f.time_updated * 1000) : null;
  const deps: NormalizedDep[] = (f.children ?? []).map((c) => ({ kind: "required", source: "steam_workshop", projectId: c.publishedfileid }));
  const votes = (f.vote_data?.votes_up ?? 0) + (f.vote_data?.votes_down ?? 0);
  return {
    gameFamily: family,
    source: "steam_workshop",
    sourceId: id,
    slugHint: `${kebab(f.title ?? "workshop-item")}-${id.slice(-6)}`,
    name: f.title ?? `Workshop item ${id}`,
    category: categoryForTags(f.tags),
    description: shortFrom(f.file_description),
    body: f.file_description?.trim() || null,
    bodyFormat: "bbcode",
    url: `https://steamcommunity.com/sharedfiles/filedetails/?id=${id}`,
    iconUrl: f.preview_url || null,
    galleryUrls: shots,
    authorName: author?.personaname ?? null,
    authorAvatarUrl: author?.avatarfull ?? null,
    authors: author?.personaname ? [{ name: author.personaname, url: author.profileurl ?? null, avatarUrl: author.avatarfull ?? null }] : undefined,
    license: null, // authors keep all rights under the Workshop EULA
    downloads: f.lifetime_subscriptions ?? f.subscriptions ?? null,
    followers: f.favorited ?? null,
    rating: votes >= 5 && f.vote_data?.score != null ? Math.round(f.vote_data.score * 50) / 10 : null,
    ratingCount: votes || null,
    categories: (f.tags ?? []).map((t) => t.display_name ?? t.tag).slice(0, 8),
    tags: (f.tags ?? []).map((t) => (t.display_name ?? t.tag).toLowerCase()).slice(0, 12),
    firstPublishedAt: f.time_created ? new Date(f.time_created * 1000) : null,
    upstreamUpdatedAt: upd,
    versions: upd
      ? [{
          versionId: `t${f.time_updated}`,
          versionNumber: upd.toISOString().slice(0, 10),
          channel: "release",
          gameVersions: [],
          loaders: ["workshop"],
          fileBytes: f.file_size ? Number(f.file_size) || null : null,
          deps,
          publishedAt: upd,
        }]
      : [],
  };
}

export const steamWorkshop: Provider = {
  key: "steam_workshop",
  label: "Steam Workshop",
  games: Object.keys(STEAM_APPIDS),
  ratePerMin: 60,
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "metadata-only",
  requiresEnv: ["STEAM_WEB_API_KEY"],
  keyHelp: "Set STEAM_WEB_API_KEY (steamcommunity.com/dev/apikey) in /opt/nxeon/.env and restart the worker.",
  async run(ctx: SyncContext): Promise<SliceResult> {
    const key = process.env.STEAM_WEB_API_KEY!;
    const only = process.env.MODSYNC_STEAM_ONLY?.split(",").filter(Boolean);
    const fams = Object.keys(STEAM_APPIDS).filter((f) => !only?.length || only.includes(f));
    const floor = Number(process.env.MODSYNC_STEAM_MIN_SUBS ?? 200);
    const perFamily = Number(process.env.MODSYNC_STEAM_MAX_PER_FAMILY ?? 6000);
    let fi = Number(ctx.cursor?.fi ?? 0);
    let cursor = String(ctx.cursor?.cursor ?? "*");
    let got = Number(ctx.cursor?.got ?? 0);
    let produced = 0;
    while (fi < fams.length) {
      const family = fams[fi];
      if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { fi, cursor, got }, done: false };
      const qt = ctx.mode === "recent" ? 21 : 9; // 21 = RankedByLastUpdatedDate, 9 = RankedByTotalUniqueSubscriptions
      const url = `${API}/IPublishedFileService/QueryFiles/v1/?key=${key}&appid=${STEAM_APPIDS[family]}&numperpage=${PAGE}&cursor=${encodeURIComponent(cursor)}&query_type=${qt}&return_previews=true&return_tags=true&return_children=true&return_vote_data=true&format=json`;
      const body = await ctx.http.json<{ response: { next_cursor?: string; publishedfiledetails?: WsFile[] } }>(url);
      const items = (body.response.publishedfiledetails ?? []).filter((f) => f.result === 1 && !f.banned && (f.visibility ?? 0) === 0 && f.title);
      let belowFloor = false;
      const keep: WsFile[] = [];
      for (const f of items) {
        if (ctx.mode === "full" && (f.subscriptions ?? 0) < floor) { belowFloor = true; break; }
        keep.push(f);
      }
      if (keep.length) {
        const players = new Map<string, WsPlayer>();
        const ids = [...new Set(keep.map((k) => k.creator).filter((x): x is string => !!x))];
        if (ids.length) {
          try {
            const pr = await ctx.http.json<{ response?: { players?: WsPlayer[] } }>(`${API}/ISteamUser/GetPlayerSummaries/v2/?key=${key}&steamids=${ids.join(",")}`);
            for (const p of pr.response?.players ?? []) players.set(p.steamid, p);
          } catch { /* avatars are optional */ }
        }
        const mods = keep.map((f) => parseWorkshopItem(f, family, f.creator ? players.get(f.creator) : undefined));
        await ctx.emit(mods);
        produced += mods.length; got += mods.length;
      }
      const next = body.response.next_cursor;
      ctx.log(`steam ${family} got=${got} cursor=${next ? "…" : "end"}`);
      const stop = belowFloor || !next || next === cursor || !items.length || got >= perFamily || (ctx.mode === "recent" && got >= 300);
      if (stop) { fi++; cursor = "*"; got = 0; } else cursor = next;
    }
    return { cursor: null, done: true };
  },
};
