export type CatalogPage = {
  mods: ModSummary[];
  total: number;
  page: number;
  totalPages: number;
  perPage: number;
};

/**
 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
 * the one honest exception: avgRating is computed from a separate ModRating
 * table with no cached column on GameMod, and Prisma's relation-aggregate
 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
 * and re-sorting by rating WITHIN each page (below) is a documented
 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
 * re-ordered by rating, not the true 25th-48th highest-rated mods
 * catalogue-wide. That is honest and fine at today's rating volumes (a small
 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
 * the rating mutation) and give this its own real orderBy.
 */
const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
  featured: [{ featured: "desc" }, { downloads: { sort: "desc", nulls: "last" } }, { popularity: "desc" }, { name: "asc" }],
  downloads: [{ downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }],
  latest: [{ createdAt: "desc" }],
  updated: [{ upstreamUpdatedAt: { sort: "desc", nulls: "last" } }, { name: "asc" }],
  rating: [{ downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }],
};

/**
 * Real, server-side, paginated + searched + sorted catalogue query — the
 * single data source behind every StoreBrowser instance (marketing and
 * portal, cross-game and per-family). Replaces the old
 * `listCatalogMods`/`searchCatalogMods` pair, which fetched (at most)
 * `CATALOG_LIST_CAP` rows once and left every control on top of it running
 * over that fixed in-memory array — fine at ~124 hand-seeded rows, silently
 * capping the catalogue at families with thousands+ of real imported rows.
 */
export async function queryCatalogMods(opts: {
  family?: string;
  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
  category?: string;
  q?: string;
  sort?: CatalogSort;
  page?: number;
  perPage?: number;
  /** Only mods whose source lists this loader/platform (GameMod.loaders). */
  loader?: string;
  /** Only mods whose source lists this game version (GameMod.gameVersions). */
  gameVersion?: string;
}): Promise<CatalogPage> {
  const sort = opts.sort ?? "featured";
  const q = (opts.q ?? "").trim();
  const where: Prisma.GameModWhereInput = {
    active: true,
    upstreamOk: true,
    ...(opts.family ? { gameFamily: opts.family } : {}),
    ...(opts.category ? { category: opts.category } : {}),
    ...(opts.loader ? { loaders: { has: opts.loader } } : {}),
    ...(opts.gameVersion ? { gameVersions: { has: opts.gameVersion } } : {}),
    ...(q
      ? {
          OR: [
            { name: { contains: q, mode: "insensitive" } },
            { category: { contains: q, mode: "insensitive" } },
            { description: { contains: q, mode: "insensitive" } },
          ],
        }
      : {}),
  };

  const total = await db.gameMod.count({ where });
  const { skip, take, page, pages, perPage } = paginate(
    { page: opts.page != null ? String(opts.page) : undefined },
    total,
    opts.perPage ?? CATALOG_PAGE_SIZE
  );

  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
  const aggs = await ratingAggs(rows.map((r) => r.id));
  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
  if (sort === "rating") {
    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
  }

  return { mods, total, page, totalPages: pages, perPage };
}

/**
 * Curated "Featured mods" rail — real `GameMod.featured` rows only (an
 * admin/import-time editorial flag, same field `ORDER_BY.featured` already
 * sorts by first), never a synthetic pick. Ordered by real downloads within
 * the featured set so the best-known featured mod leads. Returns fewer than
