/**
 * The ONLY way the mod installer talks to the internet.
 *
 * Every download URL we act on ultimately comes from a third-party API
 * response (Modrinth, Thunderstore, GitHub, a modpack's own index…), so it is
 * untrusted input. This module makes fetching it safe:
 *
 *  - https only, on every hop;
 *  - host ALLOWLIST (exact names or `*.suffix`), re-checked on every redirect,
 *    so an upstream that 302s to `http://169.254.169.254/` or to an arbitrary
 *    host is refused rather than followed;
 *  - SSRF guard at the socket: the DNS answer is checked before connecting and
 *    the connection is made to that same checked address (no TOCTOU rebinding),
 *    and private / loopback / link-local / CGNAT / multicast ranges are refused
 *    even for an allowlisted name;
 *  - a hard byte cap enforced while streaming (Content-Length is a hint, not a
 *    promise), an overall timeout, and a redirect limit;
 *  - sha1/sha256/sha512 computed on the fly and compared to whatever the
 *    upstream API published — a mismatch is a failure, never a warning.
 */
import https from "node:https";
import dns from "node:dns";
import net from "node:net";
import { createHash } from "node:crypto";

export const MOD_HOSTS: readonly string[] = [
  // Modrinth
  "api.modrinth.com", "cdn.modrinth.com",
  // Hangar (PaperMC)
  "hangar.papermc.io", "hangarcdn.papermc.io",
  // SpigotMC via Spiget (only Spigot-hosted files; external links are refused upstream of here)
  "api.spiget.org", "cdn.spiget.org",
  // Thunderstore
  "thunderstore.io", "*.thunderstore.io",
  // uMod
  "umod.org", "assets.umod.org",
  // GitHub releases
  "api.github.com", "github.com", "objects.githubusercontent.com", "release-assets.githubusercontent.com", "raw.githubusercontent.com",
  // GitLab (allowed by the Modrinth modpack spec)
  "gitlab.com",
  // Factorio mod portal
  "mods.factorio.com", "dl-mod.factorio.com",
  // ficsit.app (Satisfactory)
  "api.ficsit.app", "storage.ficsit.app",
  // Vintage Story ModDB
  "mods.vintagestory.at", "moddbcdn.vintagestory.at",
];

export class FetchError extends Error {
  constructor(message: string, readonly code: "host" | "scheme" | "ssrf" | "size" | "status" | "timeout" | "hash" | "redirect" | "network") {
    super(message);
  }
}

export function hostAllowed(host: string, allow: readonly string[] = MOD_HOSTS): boolean {
  const h = host.toLowerCase().replace(/\.$/, "");
  return allow.some((a) => (a.startsWith("*.") ? h.endsWith(a.slice(1)) && h.length > a.length - 1 : h === a));
}

/** Private, loopback, link-local, CGNAT, multicast, reserved — anything not on the public internet. */

export type Hashes = { sha1?: string | null; sha256?: string | null; sha512?: string | null };

export type FetchOptions = {
  maxBytes: number;
  timeoutMs?: number;
  maxRedirects?: number;
  headers?: Record<string, string>;
  allow?: readonly string[];
  expect?: Hashes;
  method?: "GET" | "POST";
  body?: string;
};

export type FetchResult = { bytes: Buffer; finalUrl: string; status: number; sha1: string; sha256: string; sha512: string };

/** Test seam: the worker uses the real network; unit tests inject a fake. */
export type Fetcher = (url: string, opts: FetchOptions) => Promise<FetchResult>;

const UA = "Nxeon/1.0 (mod-installer; +https://nxeon.cloud)";

function safeLookup(hostname: string, options: dns.LookupOneOptions | dns.LookupAllOptions | number, cb: (...a: any[]) => void) {
  dns.lookup(hostname, { all: true }, (err, addrs) => {
    if (err) return cb(err);
    const list = (addrs as dns.LookupAddress[]).filter((a) => !isPrivateAddress(a.address));
    if (list.length === 0) return cb(new FetchError(`refusing to connect: ${hostname} resolves to a private address`, "ssrf"));
    const all = typeof options === "object" && (options as dns.LookupAllOptions).all;
    if (all) return cb(null, list);
    cb(null, list[0].address, list[0].family);
  });
}

function once(url: URL, opts: FetchOptions, deadline: number): Promise<{ status: number; location?: string; bytes?: Buffer }> {
  return new Promise((resolve, reject) => {
    const remaining = deadline - Date.now();
    if (remaining <= 0) return reject(new FetchError("download timed out", "timeout"));
    const req = https.request(
      url,
      {
        method: opts.method ?? "GET",
        headers: { "User-Agent": UA, Accept: "*/*", ...(opts.headers ?? {}), ...(opts.body ? { "Content-Type": "application/json" } : {}) },
        lookup: safeLookup as any,
        timeout: Math.min(remaining, 30_000),
      },
      (res) => {
        const status = res.statusCode ?? 0;
        if (status >= 300 && status < 400 && res.headers.location) {
          res.resume();
          return resolve({ status, location: String(res.headers.location) });
        }
        if (status < 200 || status >= 300) {
          res.resume();
          return reject(new FetchError(`upstream answered HTTP ${status}`, "status"));
        }
        const declared = Number(res.headers["content-length"] ?? "NaN");
        if (Number.isFinite(declared) && declared > opts.maxBytes) {
          res.destroy();
          return reject(new FetchError(`file is larger than the ${Math.round(opts.maxBytes / 1048576)} MB limit`, "size"));
        }
        const chunks: Buffer[] = [];
        let n = 0;
        res.on("data", (c: Buffer) => {
          n += c.length;
          if (n > opts.maxBytes) {
            res.destroy(new FetchError(`file is larger than the ${Math.round(opts.maxBytes / 1048576)} MB limit`, "size"));
            return;
          }
          chunks.push(c);
        });
        res.on("error", (e) => reject(e instanceof FetchError ? e : new FetchError(`download interrupted: ${e.message}`, "network")));
        res.on("end", () => resolve({ status, bytes: Buffer.concat(chunks) }));
      },
    );
    const timer = setTimeout(() => req.destroy(new FetchError("download timed out", "timeout")), remaining);
    req.on("close", () => clearTimeout(timer));
    req.on("timeout", () => req.destroy(new FetchError("download timed out", "timeout")));
    req.on("error", (e) => reject(e instanceof FetchError ? e : new FetchError(`could not reach upstream: ${e.message}`, "network")));
    if (opts.body) req.write(opts.body);
    req.end();
  });
}

export function checkHashes(got: { sha1: string; sha256: string; sha512: string }, expect?: Hashes): void {
  if (!expect) return;
  for (const k of ["sha1", "sha256", "sha512"] as const) {
    const want = expect[k];
    if (want && want.toLowerCase() !== got[k]) throw new FetchError(`checksum mismatch (${k}) — the download was not what the source published`, "hash");
  }
}

export function hashAll(bytes: Buffer) {
  return {
    sha1: createHash("sha1").update(bytes).digest("hex"),
    sha256: createHash("sha256").update(bytes).digest("hex"),
    sha512: createHash("sha512").update(bytes).digest("hex"),
  };
}

export function validateUrl(raw: string, allow: readonly string[] = MOD_HOSTS): URL {
  let u: URL;
  try {
    u = new URL(raw);
  } catch {
    throw new FetchError("not a valid URL", "scheme");
  }
  if (u.protocol !== "https:") throw new FetchError(`refusing non-https URL (${u.protocol})`, "scheme");
  if (u.username || u.password) throw new FetchError("refusing a URL with embedded credentials", "scheme");
  if (u.port && u.port !== "443") throw new FetchError("refusing a non-standard port", "host");
  if (net.isIP(u.hostname.replace(/^\[|\]$/g, ""))) throw new FetchError("refusing a raw IP address", "host");
  if (!hostAllowed(u.hostname, allow)) throw new FetchError(`host ${u.hostname} is not on the mod-download allowlist`, "host");
  return u;
}

export const safeFetch: Fetcher = async (raw, opts) => {
  const allow = opts.allow ?? MOD_HOSTS;
  const deadline = Date.now() + (opts.timeoutMs ?? 180_000);
  let url = validateUrl(raw, allow);
  for (let hop = 0; hop <= (opts.maxRedirects ?? 5); hop++) {
    const r = await once(url, hop === 0 ? opts : { ...opts, method: "GET", body: undefined }, deadline);
    if (r.location) {
      url = validateUrl(new URL(r.location, url).toString(), allow);
      continue;
    }
    const bytes = r.bytes!;
    const h = hashAll(bytes);
    checkHashes(h, opts.expect);
    return { bytes, finalUrl: url.toString(), status: r.status, ...h };
  }
  throw new FetchError("too many redirects", "redirect");
};

