import fs from "node:fs/promises";
import { db } from "@/lib/db";
import { imagePath, processImage, KEY_RE, SHOT_SIZE, ICON_SIZE } from "@/lib/modsync/images";
import { IMAGE_HOSTS } from "@/lib/modsync/image-hosts";
import { safeFetch } from "@/lib/mods/safe-fetch";

export const dynamic = "force-dynamic";

/**
 * Hotlink-safe media proxy for ModMedia rows (/api/nxlabs/media/<ModMedia.id>).
 *  1. a stored copy (ModMedia.key) is served straight from the NX Labs image store (immutable);
 *  2. otherwise the upstream image is fetched through safeFetch (https, host allowlist, DNS-pinned
 *     SSRF guard, 8 MB cap), resized to WebP and served. It is PERSISTED into the store (and the row
 *     gets its key) only when the project licence allows redistribution, or for icons — the same rule
 *     lib/modsync/store.ts applies at ingest. Otherwise it is served with a 1-day public cache and
 *     never written to disk.
 * Public catalog data, no auth. Ids are cuids; a bounded concurrency gate protects the box.
 */
let inflight = 0;
const MAX_INFLIGHT = 6;

const HEADERS = (cache: string) => ({ "Content-Type": "image/webp", "Cache-Control": cache, "X-Content-Type-Options": "nosniff" });

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  if (!/^[a-z0-9]{20,40}$/i.test(id)) return new Response("Not found", { status: 404 });
  const m = await db.modMedia.findUnique({ where: { id }, select: { id: true, url: true, key: true, kind: true, gameMod: { select: { redistributable: true, active: true, upstreamOk: true } } } });
  if (!m || !m.gameMod.active) return new Response("Not found", { status: 404 });
  if (m.key && KEY_RE.test(m.key)) {
    try {
      const buf = await fs.readFile(imagePath(m.key));
      return new Response(new Uint8Array(buf), { headers: HEADERS("public, max-age=31536000, immutable") });
    } catch {
      /* fall through to a live fetch */
    }
  }
  if (inflight >= MAX_INFLIGHT) return new Response("Busy", { status: 503, headers: { "Retry-After": "3" } });
  inflight++;
  try {
    const r = await safeFetch(m.url, { maxBytes: 8 * 1024 ** 2, timeoutMs: 15_000, maxRedirects: 3, allow: IMAGE_HOSTS, headers: { Accept: "image/*" } });
    const persist = m.gameMod.redistributable || m.kind === "icon";
    const out = await processImage(r.bytes, m.kind === "icon" ? ICON_SIZE : SHOT_SIZE, persist);
    if (!out) return new Response("Not found", { status: 404 });
    if (out.stored) await db.modMedia.update({ where: { id: m.id }, data: { key: out.key, mirrored: m.kind !== "icon" } }).catch(() => {});
    return new Response(new Uint8Array(out.out), { headers: HEADERS(out.stored ? "public, max-age=31536000, immutable" : "public, max-age=86400") });
  } catch {
    return new Response("Not found", { status: 404 });
  } finally {
    inflight--;
  }
}
