body='''const PER_PAGE = 50;
type SP = { q?: string; family?: string; source?: string; status?: string; page?: string };

export default async function AdminGameModsPage({ searchParams }: { searchParams: Promise<SP> }) {
  await requireArea("billing");
  const sp = await searchParams;
  const q = (sp.q ?? "").trim().slice(0, 80);
  const family = sp.family && /^[a-z0-9-]{1,40}$/.test(sp.family) ? sp.family : "";
  const source = sp.source && /^[a-z_0-9]{1,40}$/.test(sp.source) ? sp.source : "";
  const status = ["active", "disabled", "unsupported", "duplicate", "unverified"].includes(sp.status ?? "") ? (sp.status as string) : "";

  const where: Prisma.GameModWhereInput = {
    ...(family ? { gameFamily: family } : {}),
    ...(source ? { source } : {}),
    ...(status === "active" ? { active: true, upstreamOk: true, duplicateOfId: null } : {}),
    ...(status === "disabled" ? { active: false } : {}),
    ...(status === "unsupported" ? { upstreamOk: false } : {}),
    ...(status === "duplicate" ? { duplicateOfId: { not: null } } : {}),
    ...(status === "unverified" ? { verifiedAt: null } : {}),
    ...(q ? { OR: [{ name: { contains: q, mode: "insensitive" } }, { slug: { contains: q, mode: "insensitive" } }, { sourceId: { equals: q } }, { authorName: { contains: q, mode: "insensitive" } }] } : {}),
  };

  // Server-side: only ONE page of rows is ever loaded (the catalog has 64k+).
  const [total, grand, unsupported, duplicates, families, sources] = await Promise.all([
    db.gameMod.count({ where }),
    db.gameMod.count(),
    db.gameMod.count({ where: { upstreamOk: false } }),
    db.gameMod.count({ where: { duplicateOfId: { not: null } } }),
    db.gameMod.groupBy({ by: ["gameFamily"], _count: { _all: true }, orderBy: { gameFamily: "asc" } }),
    db.gameMod.groupBy({ by: ["source"], _count: { _all: true }, orderBy: { source: "asc" } }),
  ]);
  const pg = paginate(sp, total, PER_PAGE);
  const mods = await db.gameMod.findMany({
    where,
    orderBy: [{ gameFamily: "asc" }, { downloads: { sort: "desc", nulls: "last" } }, { name: "asc" }, { id: "asc" }],
    skip: pg.skip,
    take: pg.take,
  });
  const filterParams = { q, family, source, status };
  const sel = "rounded-md border border-white/10 bg-white/5 px-2 py-1.5 text-sm text-slate-200";

  return (
    <div>
      <PageHeader
        title="NxLabs mod catalog"
        sub="Search, filter and toggle catalog rows. Verified facts come from the providers (lib/modsync) and scripts/verify-gamemods.ts, never hand-typed here."
      >
        <Badge tone="brand">{grand.toLocaleString()} mods</Badge>
        {duplicates > 0 && <Badge tone="slate">{duplicates.toLocaleString()} duplicates linked</Badge>}
        {unsupported > 0 && <Badge tone="red">{unsupported.toLocaleString()} unsupported</Badge>}
      </PageHeader>

      <form method="get" className="card mb-4 flex flex-wrap items-end gap-2">
        <input name="q" defaultValue={q} placeholder="Search name, slug, author or source id" className={`${sel} min-w-[16rem] flex-1`} />
        <select name="family" defaultValue={family} className={sel}>
          <option value="">All games</option>
          {families.map((f) => (
            <option key={f.gameFamily} value={f.gameFamily}>{GAME_DISPLAY[f.gameFamily as GameFamily]?.name ?? f.gameFamily} ({f._count._all.toLocaleString()})</option>
          ))}
        </select>
        <select name="source" defaultValue={source} className={sel}>
          <option value="">All sources</option>
          {sources.map((x) => (
            <option key={x.source} value={x.source}>{SOURCE_LABEL[x.source] ?? x.source} ({x._count._all.toLocaleString()})</option>
          ))}
        </select>
        <select name="status" defaultValue={status} className={sel}>
          <option value="">Any status</option>
          <option value="active">Live (active, supported, canonical)</option>
          <option value="disabled">Disabled</option>
          <option value="unsupported">Unsupported upstream</option>
          <option value="duplicate">Duplicates (hidden)</option>
          <option value="unverified">Never verified</option>
        </select>
        <button type="submit" className="btn-primary py-1.5 text-sm">Filter</button>
      </form>

      <p className="mb-3 text-sm text-slate-400">
        {total.toLocaleString()} match{total === 1 ? "" : "es"} · page {pg.page} of {pg.pages}
      </p>

      <div className="space-y-2">
        {mods.map((m) => (
          <div key={m.id} className="card">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="flex min-w-0 items-center gap-3">
                {m.iconUrl ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={m.iconUrl} alt="" width={36} height={36} loading="lazy" className="h-9 w-9 shrink-0 rounded-md border border-white/10 object-cover" />
                ) : (
                  <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-md border border-white/10 bg-white/5 text-xs text-slate-500">{m.name.slice(0, 1)}</div>
                )}
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-semibold text-white">{m.name}</span>
                    {m.featured && <Badge tone="brand">Featured</Badge>}
                    <Badge tone={m.active ? "green" : "slate"}>{m.active ? "Active" : "Disabled"}</Badge>
                    {!m.upstreamOk && <Badge tone="red">Unsupported</Badge>}
                    {m.duplicateOfId && <Badge tone="slate">Duplicate</Badge>}
                    {!m.verifiedAt && <Badge tone="slate">Unverified</Badge>}
                  </div>
                  <p className="mt-1 text-xs text-slate-400">
                    {GAME_DISPLAY[m.gameFamily as GameFamily]?.name ?? m.gameFamily} · {m.category} · {SOURCE_LABEL[m.source] ?? m.source} · slug: {m.slug}
                    {m.downloads != null && ` · ${formatDownloads(m.downloads)} downloads`}
                    {m.license && ` · ${m.license}`}
                  </p>
                  {!m.upstreamOk && m.upstreamNote && <p className="mt-1 text-xs text-red-400">{m.upstreamNote}</p>}
                  <p className="mt-0.5 text-xs text-slate-500">{m.verifiedAt ? `Verified ${m.verifiedAt.toISOString().slice(0, 10)}` : "Never verified"}</p>
                </div>
              </div>
              <div className="flex flex-wrap items-center gap-2">
                <ToggleGameModButton id={m.id} active={m.active} />
                <MarkUnsupportedButton id={m.id} upstreamOk={m.upstreamOk} />
              </div>
            </div>
          </div>
        ))}
        {mods.length === 0 && <div className="card text-sm text-slate-400">No mods match these filters.</div>}
      </div>

      {pg.pages > 1 && (
        <div className="mt-4 flex items-center justify-between text-sm text-slate-400">
          <span>{pg.skip + 1}–{Math.min(pg.skip + pg.take, total)} of {total.toLocaleString()}</span>
