  const where: Prisma.GameModWhereInput = {
    ...(family ? { gameFamily: family } : {}),
    ...(source ? { source } : {}),
    ...(status === "active" ? { active: true, upstreamOk: true, duplicateOfId: null } : {}),
    ...(status === "disabled" ? { active: false } : {}),
    ...(status === "unsupported" ? { upstreamOk: false } : {}),
    ...(status === "duplicate" ? { duplicateOfId: { not: null } } : {}),
    ...(status === "unverified" ? { verifiedAt: null } : {}),
    ...(q ? { OR: [{ name: { contains: q, mode: "insensitive" } }, { slug: { contains: q, mode: "insensitive" } }, { sourceId: { equals: q } }, { authorName: { contains: q, mode: "insensitive" } }] } : {}),
  };

