    db.gameMod.count({ where: { duplicateOfId: { not: null } } }),
    db.gameMod.groupBy({ by: ["gameFamily"], _count: { _all: true }, orderBy: { gameFamily: "asc" } }),
    db.gameMod.groupBy({ by: ["source"], _count: { _all: true }, orderBy: { source: "asc" } }),
  ]);
  const pg = paginate(sp, total, PER_PAGE);
  const mods = await db.gameMod.findMany({
