  assert.equal(isRedistributable(m.license), false);
  assert.equal(m.bodyFormat, "markdown");
  assert.deepEqual(m.media!.map((x) => x.url), ["https://i.imgur.com/a.png"]);
  assert.ok(m.versions!.length >= 1 && m.versions![0].changelog === "## 1.0\n- fixed");
  assert.ok(m.versions!.every((v, i, a) => i === 0 || a[i - 1].publishedAt! >= v.publishedAt!));
  assert.ok(m.versions![0].deps!.every((d) => d.kind === "required" && d.source === "thunderstore"));
  assert.match(m.versions![0].fileUrl!, /^https:\/\//);
});

test("thunderstore: quality gate + dependency + side parsing", () => {
  const pkgs = fx("thunderstore-palworld.json") as TsPackage[];
  assert.equal(tsExcluded(pkgs[2]), "deprecated");
  assert.equal(tsExcluded(pkgs[0]), null);
  assert.equal(tsExcluded({ ...pkgs[0], categories: ["Client-side"] }), "client-only");
  assert.equal(tsExcluded({ ...pkgs[0], has_nsfw_content: true }), "nsfw");
  assert.deepEqual(parseTsDep("denikson-BepInExPack_Valheim-5.4.2333"), { kind: "required", source: "thunderstore", projectId: "denikson-BepInExPack_Valheim", name: "BepInExPack_Valheim", versionId: "5.4.2333" });
  assert.equal(parseTsDep("garbage"), null);
  assert.deepEqual(tsSides(["Server-side"]), { clientSide: "optional", serverSide: "required" });
  assert.deepEqual(tsSides(["Server-side", "Client-side"]), { clientSide: "optional", serverSide: "optional" });
  assert.deepEqual(tsSides(["Mods"]), { clientSide: null, serverSide: null });
