test("json-stream: yields array elements across arbitrary chunk boundaries, braces/quotes in strings, unicode", async () => {
  const items = [{ a: 1, s: 'he said "}{" \\ ok' }, { a: 2, n: { x: [1, { y: "é€😀" }] } }, { a: 3 }];
  const text = JSON.stringify(items, null, 1);
  const buf = Buffer.from(text, "utf8");
  for (const size of [1, 2, 3, 7, 64, buf.length]) {
    const chunks: Buffer[] = [];
    for (let i = 0; i < buf.length; i += size) chunks.push(buf.subarray(i, i + size));
    const got: unknown[] = [];
    for await (const o of streamJsonArray(Readable.from(chunks))) got.push(o);
    assert.deepEqual(got, items, `chunk size ${size}`);
  }
});

