/**
 * Modrinth (https://docs.modrinth.com/api/) — game: minecraft.
 * Mirror-eligible: per-project license is machine readable (SPDX `license.id`);
 * files are only stored when that license grants redistribution
 * (lib/modsync/license.ts). Rate limit 300/min; we use 240.
 */
import type { NormalizedMod, NormalizedVersion, Provider, SliceResult, SyncContext } from "../types";

const API = "https://api.modrinth.com/v2";
const TYPES = ["mod", "plugin", "resourcepack", "shader", "datapack", "modpack"] as const;
const LABEL: Record<string, string> = { mod: "Mods", plugin: "Plugins", resourcepack: "Resource Packs", shader: "Shaders", datapack: "Datapacks", modpack: "Modpacks" };
const SERVER_ENVS = ["server_only", "dedicated_server_only", "server_only_client_optional", "client_and_server", "client_or_server", "client_or_server_prefers_both"];
const PAGE = 100;
const VERSIONS_PER_MOD = 5;

export interface MrProject {
  id: string; slug: string; title: string; description?: string; body?: string; project_type: string;
  categories?: string[]; additional_categories?: string[]; loaders?: string[]; game_versions?: string[];
  downloads?: number; followers?: number; icon_url?: string | null; source_url?: string | null;
  server_side?: string; updated?: string; versions?: string[]; team?: string;
    downloads: p.downloads ?? null,
    followers: p.followers ?? null,
    categories: [...(p.categories ?? []), ...(p.additional_categories ?? [])],
    tags: p.loaders ?? [],
    gameVersions: p.game_versions ?? [],
    loaders: p.loaders ?? [],
    serverSide: p.server_side ?? null,
    upstreamUpdatedAt: p.updated ? new Date(p.updated) : null,
    versions: vs,
  };
}

export const modrinth: Provider = {
  key: "modrinth",
  label: "Modrinth",
  games: ["minecraft"],
  ratePerMin: 240,
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "mirror-if-licensed",
  async run(ctx: SyncContext): Promise<SliceResult> {
    let ti = Number(ctx.cursor?.ti ?? 0);
    let offset = Number(ctx.cursor?.offset ?? 0);
    const minDl = Number(process.env.MODSYNC_MODRINTH_MIN_DOWNLOADS ?? 1000);
    const types = (process.env.MODSYNC_MODRINTH_TYPES?.split(",") ?? [...TYPES]).filter((t) => (TYPES as readonly string[]).includes(t));
    let produced = 0;
    while (ti < types.length) {
      const pt = types[ti];
      const envs = pt === "plugin" ? [...SERVER_ENVS, "unknown"] : SERVER_ENVS;
      const facets = JSON.stringify([[`project_type:${pt}`], envs.map((e) => `environment:${e}`), [`downloads>=${minDl}`]]);
      while (true) {
        if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { ti, offset }, done: false };
        const q = `${API}/search?limit=${PAGE}&offset=${offset}&index=${ctx.mode === "recent" ? "updated" : "downloads"}&facets=${encodeURIComponent(facets)}`;
        const body = await ctx.http.json<{ hits: { project_id: string; author?: string }[]; total_hits: number }>(q);
        if (!body.hits.length) break;
        const ids = body.hits.map((h) => h.project_id);
        const projects = await ctx.http.json<MrProject[]>(`${API}/projects?ids=${encodeURIComponent(JSON.stringify(ids))}`);
        const verIds = projects.flatMap((p) => (p.versions ?? []).slice(-VERSIONS_PER_MOD));
        const versions: MrVersion[] = [];
        for (let i = 0; i < verIds.length; i += 250) {
          versions.push(...(await ctx.http.json<MrVersion[]>(`${API}/versions?ids=${encodeURIComponent(JSON.stringify(verIds.slice(i, i + 250)))}`)));
        }
        const byProject = new Map<string, MrVersion[]>();
        for (const v of versions) byProject.set(v.project_id, [...(byProject.get(v.project_id) ?? []), v]);
        const authorOf = new Map(body.hits.map((h) => [h.project_id, h.author ?? null]));
        await ctx.emit(projects.map((p) => parseModrinthProject(p, authorOf.get(p.id) ?? null, byProject.get(p.id) ?? [])));
        produced += projects.length;
        offset += PAGE;
        ctx.log(`modrinth ${pt} offset=${offset}/${Math.min(body.total_hits, 10000)}`);
        // Meilisearch hard cap: offset+limit <= 10000.
        if (offset >= body.total_hits || offset + PAGE > 10000) break;
        // "recent" mode: a few pages of newest-updated is enough to pick up changes.
        if (ctx.mode === "recent" && offset >= PAGE * 5) break;
      }
      ti++;
      offset = 0;
    }
    return { cursor: null, done: true };
  },
};
