cat > lib/modsync/providers/umod.ts <<'E'
/**
 * uMod (Oxide / Carbon plugins) — Rust, 7 Days to Die (+ other uMod games we host). Reads ONLY the open
 * static data uMod publishes for third parties on `assets.umod.org`:
 *   /plugins/manifest.json      one object of ~1,700 plugins {Key: {title, description, icon, tags, url, games[]}}
 *   /plugins/<Key>.json         license, repository, maintainers, branches.master.<ver>.{download_url, checksum(sha1), requires, suggests}
 * uMod's developer docs call these endpoints public and say third parties may host a mirror of the manifest.
 * We NEVER request umod.org itself (its robots.txt/ToS sit behind a Cloudflare challenge we must not bypass)
 * and never scrape HTML.
 *
 * Policy: METADATA + LINK-THROUGH (some plugins are "MIT with distribution exclusivity for uMod.org"),
 * never mirrored; the Rust installer fetches the .cs from assets.umod.org at install time.
 * Plugins tagged `broken` in the manifest are skipped. Rate 30/min, ETag-free (manifest is a 24 h cached
 * 700 KB file); per-plugin files are only re-read in a `full` pass or when we have never seen the plugin.
 */
import type { NormalizedDep, NormalizedMod, NormalizedVersion, Provider, SliceResult, SyncContext } from "../types";

const ASSETS = "https://assets.umod.org/plugins";

/** uMod game slug -> our gameFamily (only games we host). */
export const UMOD_GAMES: Record<string, string> = { rust: "rust", "7-days-to-die": "sdtd", "the-forest": "theforest" };

export interface UmManifestEntry { title?: string; description?: string; icon?: string; tags?: string | string[]; maintainers?: unknown; url?: string; games?: string[] }
export interface UmBranchVersion { formatted?: string; download_url?: string; checksum?: string; published_at?: string; requires?: Record<string, string | unknown>; suggests?: Record<string, string | unknown> }
export interface UmPlugin {
  name?: string; title?: string; description?: string; url?: string; published_at?: string; icon?: string; tags?: string[]; type?: string; repository?: string;
  watchers?: { count?: number }; license?: { name?: string | null; url?: string | null } | null;
  games?: Record<string, { name?: string }>; maintainers?: Record<string, { name: string; url?: string; icon?: string | null; donate_url?: string | null }>;
  branches?: { master?: Record<string, UmBranchVersion> };
}

const UM_LICENSE: Record<string, string> = { gpl3: "GPL-3.0", gpl2: "GPL-2.0", mit: "MIT", apache2: "Apache-2.0", lgpl3: "LGPL-3.0", agpl3: "AGPL-3.0", bsd3: "BSD-3-Clause", bsd2: "BSD-2-Clause", cc0: "CC0-1.0", mpl2: "MPL-2.0", unlicense: "Unlicense" };
export const umodLicense = (l: string | null | undefined) => (l ? UM_LICENSE[l.toLowerCase()] ?? l : null);
const slugOf = (url: string | undefined, key: string) => /\/plugins\/([^/?#]+)/.exec(url ?? "")?.[1] ?? key.toLowerCase();
const tagList = (t: string | string[] | undefined) => (Array.isArray(t) ? t : (t ?? "").split(",")).map((x) => x.trim()).filter(Boolean);
const ts = (s?: string) => (s ? new Date(s.replace(" ", "T") + "Z") : null);
const cmpVer = (a: string, b: string) => a.localeCompare(b, undefined, { numeric: true });

export function parseUmodPlugin(key: string, p: UmPlugin, family: string, entry?: UmManifestEntry): NormalizedMod {
  const tags = tagList(p.tags ?? entry?.tags);
  const maint = Object.values(p.maintainers ?? {});
  const master = p.branches?.master ?? {};
  const vers: NormalizedVersion[] = Object.entries(master)
    .sort(([a, x], [b, y]) => +(ts(y.published_at) ?? 0) - +(ts(x.published_at) ?? 0) || cmpVer(b, a))
    .slice(0, 25)
    .map(([ver, v]) => {
      const dep = (m: Record<string, unknown> | undefined, kind: "required" | "optional"): NormalizedDep[] => Object.keys(m ?? {}).map((n) => ({ kind, source: "umod", projectId: n, name: n }));
      return {
        versionId: ver,
        versionNumber: ver,
        channel: "release",
        gameVersions: [],
        loaders: ["oxide", "carbon"],
        fileName: v.download_url ? v.download_url.split("/").pop() ?? null : null,
        fileUrl: v.download_url ?? null,
        sha1: v.checksum ?? null,
        deps: [...dep(v.requires as Record<string, unknown>, "required"), ...dep(v.suggests as Record<string, unknown>, "optional")],
        dependencies: { requires: v.requires ?? {}, suggests: v.suggests ?? {} },
        serverSideReq: "required",
        clientSide: "unsupported",
        publishedAt: ts(v.published_at),
      };
    });
  const donate = maint.find((m) => m.donate_url)?.donate_url ?? null;
  const repo = p.repository && /^https:\/\//.test(p.repository) ? p.repository : null;
  return {
    gameFamily: family,
    source: "umod",
    sourceId: slugOf(p.url ?? entry?.url, key),
    slugHint: slugOf(p.url ?? entry?.url, key),
    name: p.title || entry?.title || key,
    category: "Plugins",
    description: p.description || entry?.description || null,
    body: null, // uMod exposes no long description; never invent one
    url: p.url ?? entry?.url ?? null,
    sourceUrl: repo,
    iconUrl: p.icon || entry?.icon || null,
    authorName: maint[0]?.name ?? null,
    authors: maint.map((m) => ({ name: m.name, url: m.url ?? null, avatarUrl: m.icon ?? null })),
    license: umodLicense(p.license?.name),
    licenseUrl: p.license?.url ?? null,
    donationUrl: donate && /^https:/.test(donate) ? donate : null,
    downloads: null, // not exposed in the open files
    followers: p.watchers?.count ?? null,
    categories: tags.filter((t) => !Object.keys(UMOD_GAMES).includes(t) && t !== "rust").slice(0, 3),
    tags,
    loaders: ["oxide", "carbon"],
    serverSide: "required",
    clientSide: "unsupported",
    firstPublishedAt: ts(p.published_at),
    upstreamUpdatedAt: vers[0]?.publishedAt ?? ts(p.published_at),
    versions: vers,
  };
}

export const umod: Provider = {
  key: "umod",
  label: "uMod (Oxide / Carbon) via assets.umod.org",
  games: Object.values(UMOD_GAMES),
  ratePerMin: Number(process.env.MODSYNC_UMOD_RATE ?? 30),
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "metadata-only",
  async run(ctx: SyncContext): Promise<SliceResult> {
    const manifest = await ctx.http.json<Record<string, UmManifestEntry>>(`${ASSETS}/manifest.json`);
    const keys = Object.keys(manifest).filter((k) => {
      const e = manifest[k];
      return (e.games ?? []).some((g) => UMOD_GAMES[g]) && !tagList(e.tags).includes("broken");
    }).sort();
    let i = Number(ctx.cursor?.i ?? 0);
    let produced = 0;
    while (i < keys.length) {
      if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { i }, done: false };
      const chunk = keys.slice(i, i + 20);
      const known = await ctx.known("umod", chunk.map((k) => slugOf(manifest[k].url, k)));
      const mods: NormalizedMod[] = [];
      for (const k of chunk) {
        const e = manifest[k];
        const slug = slugOf(e.url, k);
        const fams = [...new Set((e.games ?? []).map((g) => UMOD_GAMES[g]).filter(Boolean))];
        const have = known.get(slug);
        if (have && have.versionCount > 0 && ctx.mode === "recent") continue; // daily pass: only plugins we have never read
        try {
          const p = await ctx.http.json<UmPlugin>(`${ASSETS}/${encodeURIComponent(k)}.json`);
          for (const f of fams) mods.push(parseUmodPlugin(k, p, f, e));
        } catch (err) {
          ctx.log(`umod ${k} failed: ${err instanceof Error ? err.message : err}`);
        }
      }
      if (mods.length) { await ctx.emit(mods); produced += mods.length; }
      i += chunk.length;
      ctx.log(`umod ${i}/${keys.length}`);
    }
    return { cursor: null, done: true };
  },
};
