cat > lib/modsync/providers/github.ts <<'E'
/**
 * GitHub — a CURATED allow-list only (lib/modsync/github-allowlist.ts: Oxide, Carbon, CounterStrikeSharp,
 * Metamod:Source, TShock, tModLoader, Geyser, ... plus plugins already in the catalogue). Per repo:
 * `GET repos/<r>` (licence, description, stars, links), `GET repos/<r>/readme` (raw markdown = long
 * description), `GET repos/<r>/releases` (assets -> versions with browser_download_url, size and the
 * sha256 digest GitHub publishes). No search, no crawling.
 *
 * Licence gate: `license.spdx_id`; `NOASSERTION` / none => null => NOT redistributable => link-through.
 * Policy mirror-if-licensed: only SPDX-open repos have their release assets mirrored (never above the
 * per-file cap). Optional GITHUB_TOKEN (5,000 req/h); without it we self-limit to 1 req/min (60/h).
 * Unchanged repos (pushed_at not newer than what we stored, versions present) cost ONE request.
 */
import { imagesFromBody } from "../media";
import { GITHUB_ALLOWLIST, type GhEntry } from "../github-allowlist";
import type { NormalizedMod, NormalizedVersion, Provider, SliceResult, SyncContext } from "../types";

const API = "https://api.github.com";

export interface GhRepo {
  full_name: string; name: string; description?: string | null; html_url: string; homepage?: string | null;
  stargazers_count?: number; forks_count?: number; open_issues_count?: number; has_issues?: boolean; has_wiki?: boolean;
  archived?: boolean; disabled?: boolean; pushed_at?: string; created_at?: string; topics?: string[];
  license?: { spdx_id?: string | null; name?: string | null; url?: string | null } | null;
  owner?: { login?: string; avatar_url?: string; html_url?: string };
}
export interface GhRelease {
  id: number; tag_name: string; name?: string | null; body?: string | null; draft?: boolean; prerelease?: boolean; published_at?: string | null;
  assets?: { id: number; name: string; size: number; browser_download_url: string; digest?: string | null; download_count?: number; content_type?: string }[];
}

export const ghLicense = (r: GhRepo): string | null => {
  const id = r.license?.spdx_id;
  return id && id !== "NOASSERTION" && id !== "NONE" ? id : null;
};

export function parseGithubRepo(entry: GhEntry, r: GhRepo, releases: GhRelease[], readme: string | null): NormalizedMod {
  const re = entry.assets ? new RegExp(entry.assets, "i") : null;
  const versions: NormalizedVersion[] = releases
    .filter((x) => !x.draft)
    .flatMap((rel) => {
      const picked = (rel.assets ?? []).filter((a) => !re || re.test(a.name));
      const a = picked[0];
      if (!a) return [];
      const sha = a.digest?.startsWith("sha256:") ? a.digest.slice(7) : null;
      return [{
        versionId: String(rel.id),
        versionNumber: rel.tag_name.slice(0, 120),
        channel: rel.prerelease ? ("beta" as const) : ("release" as const),
        gameVersions: [],
        loaders: entry.variant ? [entry.variant] : [],
        fileName: a.name,
        fileUrl: a.browser_download_url,
        fileBytes: a.size,
        sha256: sha,
        downloads: a.download_count ?? null,
        changelog: rel.body || null,
        publishedAt: rel.published_at ? new Date(rel.published_at) : null,
        serverSideReq: "required",
      }];
    })
    .slice(0, 25);
  const license = ghLicense(r);
  return {
    gameFamily: entry.family,
    source: "github",
    sourceId: r.full_name,
    slugHint: r.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "repo",
    name: r.name,
    category: entry.category,
    description: r.description || null,
    body: readme,
    bodyFormat: "markdown",
    url: r.html_url,
    sourceUrl: r.html_url,
    websiteUrl: r.homepage && /^https:\/\//.test(r.homepage) ? r.homepage : null,
    issuesUrl: r.has_issues ? `${r.html_url}/issues` : null,
    wikiUrl: r.has_wiki ? `${r.html_url}/wiki` : null,
    iconUrl: r.owner?.avatar_url ?? null,
    media: imagesFromBody(readme).map((u) => ({ kind: "screenshot" as const, url: u })),
    authorName: r.owner?.login ?? null,
    authors: r.owner?.login ? [{ name: r.owner.login, url: r.owner.html_url ?? null, avatarUrl: r.owner.avatar_url ?? null }] : undefined,
    license,
    licenseUrl: r.license?.url ?? null,
    downloads: releases.reduce((n, x) => n + (x.assets ?? []).reduce((m, a) => m + (a.download_count ?? 0), 0), 0) || null,
    followers: r.stargazers_count ?? null,
    categories: [entry.category],
    tags: r.topics ?? [],
    loaders: entry.variant ? [entry.variant] : [],
    serverSide: "required",
    clientSide: "unsupported",
    appliesToVariant: entry.variant ?? null,
    firstPublishedAt: r.created_at ? new Date(r.created_at) : null,
    upstreamUpdatedAt: r.pushed_at ? new Date(r.pushed_at) : null,
    versions,
  };
}

export const github: Provider = {
  key: "github",
  label: "GitHub (curated allow-list)",
  games: [...new Set(GITHUB_ALLOWLIST.map((e) => e.family))],
  ratePerMin: process.env.GITHUB_TOKEN ? 60 : 1,
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "mirror-if-licensed",
  headers: () => ({ Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", ...(process.env.GITHUB_TOKEN ? { Authorization: `Bearer ${process.env.GITHUB_TOKEN}` } : {}) }),
  async run(ctx: SyncContext): Promise<SliceResult> {
    let i = Number(ctx.cursor?.i ?? 0);
    let produced = 0;
    const list = GITHUB_ALLOWLIST;
    while (i < list.length) {
      if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { i }, done: false };
      const e = list[i];
      try {
        const r = await ctx.http.json<GhRepo>(`${API}/repos/${e.repo}`);
        const known = (await ctx.known("github", [r.full_name])).get(r.full_name);
        const pushed = r.pushed_at ? new Date(r.pushed_at) : null;
        const fresh = known && known.versionCount > 0 && known.upstreamUpdatedAt && pushed && +known.upstreamUpdatedAt >= +pushed;
        if (!fresh && !r.archived || (!fresh && r.archived && !known)) {
          const rel = await ctx.http.json<GhRelease[]>(`${API}/repos/${e.repo}/releases?per_page=10`).catch(() => [] as GhRelease[]);
          let readme: string | null = null;
          try {
            const res = await ctx.http.request(`${API}/repos/${e.repo}/readme`, { headers: { Accept: "application/vnd.github.raw+json" } });
            if (res.ok) readme = (await res.text()).slice(0, 60_000) || null;
          } catch { /* README is optional */ }
          await ctx.emit([parseGithubRepo(e, r, rel, readme)]);
          produced++;
        }
      } catch (err) {
        ctx.log(`github ${e.repo} failed: ${err instanceof Error ? err.message : err}`);
      }
      i++;
    }
    return { cursor: null, done: true };
  },
};
