new='''const FACET_CAP = 9900; // Modrinth search hard-caps offset+limit at 10 000 per query

/**
 * Number of server-relevant projects of a type inside a downloads window [lo, hi) (hi 0 = unbounded).
 * One tiny search call (limit=1) — used to bisect a window until it fits under the 10k result cap, so a
 * full pass can reach EVERY project (not just the first 10k of each type).
 */
export async function modrinthWindowCount(ctx: SyncContext, pt: string, lo: number, hi: number): Promise<number> {
  const r = await ctx.http.json<{ total_hits: number }>(`${API}/search?limit=1&facets=${encodeURIComponent(JSON.stringify(facetsFor(pt, lo, hi)))}`);
  return r.total_hits;
}

export function facetsFor(pt: string, lo: number, hi: number): string[][] {
  const envs = pt === "plugin" ? [...SERVER_ENVS, "unknown"] : SERVER_ENVS;
  const f: string[][] = [[`project_type:${pt}`], envs.map((e) => `environment:${e}`), [`downloads>=${lo}`]];
  if (hi > 0) f.push([`downloads<${hi}`]);
  return f;
}

/** Highest-downloads-first windows: given the exclusive upper bound `hi`, find the lowest `lo` (>= floor) whose window fits the cap. */
export async function nextWindow(ctx: SyncContext, pt: string, hi: number, floor: number): Promise<{ lo: number; hi: number; total: number } | null> {
  if (hi > 0 && hi <= floor) return null;
  if ((await modrinthWindowCount(ctx, pt, floor, hi)) <= FACET_CAP) return { lo: floor, hi, total: await modrinthWindowCount(ctx, pt, floor, hi) };
  let a = floor, b = hi > 0 ? hi : 1_000_000_000; // invariant: count(a..hi) > cap, count(b..hi) <= cap (b may be empty)
  while (b - a > 1) {
    const mid = Math.floor((a + b) / 2);
    if ((await modrinthWindowCount(ctx, pt, mid, hi)) <= FACET_CAP) b = mid; else a = mid;
  }
  return { lo: b, hi, total: await modrinthWindowCount(ctx, pt, b, hi) };
}

export const modrinth: Provider = {
  key: "modrinth",
  label: "Modrinth",
  games: ["minecraft"],
  ratePerMin: 240,
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "mirror-if-licensed",
  async run(ctx: SyncContext): Promise<SliceResult> {
    let ti = Number(ctx.cursor?.ti ?? 0);
    let offset = Number(ctx.cursor?.offset ?? 0);
    let lo = ctx.cursor?.lo != null ? Number(ctx.cursor.lo) : -1; // -1 = window not chosen yet
    let hi = Number(ctx.cursor?.hi ?? 0);
    const minDl = Number(process.env.MODSYNC_MODRINTH_MIN_DOWNLOADS ?? 10);
    const types = (process.env.MODSYNC_MODRINTH_TYPES?.split(",") ?? [...TYPES]).filter((t) => (TYPES as readonly string[]).includes(t));
    let produced = 0;
    while (ti < types.length) {
      const pt = types[ti];
      if (ctx.mode === "recent") {
        // Cheap freshness pass: newest-updated pages only, no windowing.
        const facets = JSON.stringify(facetsFor(pt, minDl, 0));
        for (let o = 0; o < PAGE * 5; o += PAGE) {
          if (Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { ti, offset: 0 }, done: false };
          const body = await ctx.http.json<{ hits: { project_id: string; author?: string }[] }>(`${API}/search?limit=${PAGE}&offset=${o}&index=updated&facets=${encodeURIComponent(facets)}`);
          if (!body.hits.length) break;
          produced += await this_page(ctx, pt, body.hits);
        }
        ti++; offset = 0;
        continue;
      }
      if (lo < 0) {
        const w = await nextWindow(ctx, pt, hi, minDl);
        if (!w || w.total === 0) { ti++; offset = 0; hi = 0; lo = -1; continue; }
        lo = w.lo; offset = 0;
        ctx.log(`modrinth ${pt} window downloads [${lo}, ${hi || "inf"}) = ${w.total}`);
      }
      const facets = JSON.stringify(facetsFor(pt, lo, hi));
      while (true) {
        if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { ti, offset, lo, hi }, done: false };
        const body = await ctx.http.json<{ hits: { project_id: string; author?: string }[]; total_hits: number }>(`${API}/search?limit=${PAGE}&offset=${offset}&index=downloads&facets=${encodeURIComponent(facets)}`);
        if (!body.hits.length) break;
        produced += await this_page(ctx, pt, body.hits);
        offset += PAGE;
        ctx.log(`modrinth ${pt} [${lo},${hi || "inf"}) offset=${offset}/${body.total_hits}`);
        if (offset >= body.total_hits) break;
      }
      // window exhausted: continue below it (lower downloads), or finish the type
      if (lo <= minDl) { ti++; hi = 0; lo = -1; offset = 0; } else { hi = lo; lo = -1; offset = 0; }
    }
    return { cursor: null, done: true };
  },
};

/** Fetch + emit one page of hits; unchanged projects (same `updated`, versions stored) are skipped — no version calls, no writes. */
async function this_page(ctx: SyncContext, _pt: string, hits: { project_id: string; author?: string }[]): Promise<number> {
  const ids = hits.map((h) => h.project_id);
  const projects = await ctx.http.json<MrProject[]>(`${API}/projects?ids=${encodeURIComponent(JSON.stringify(ids))}`);
  const known = await ctx.known("modrinth", projects.map((p) => p.slug));
  const changed = projects.filter((p) => {
    const k = known.get(p.slug);
    return !(k && k.versionCount > 0 && k.upstreamUpdatedAt && p.updated && +k.upstreamUpdatedAt >= +new Date(p.updated));
  });
  if (!changed.length) return 0;
  const verIds = changed.flatMap((p) => (p.versions ?? []).slice(-VERSIONS_PER_MOD));
  const versions: MrVersion[] = [];
  for (let i = 0; i < verIds.length; i += 250) {
    versions.push(...(await ctx.http.json<MrVersion[]>(`${API}/versions?ids=${encodeURIComponent(JSON.stringify(verIds.slice(i, i + 250)))}`)));
  }
  const byProject = new Map<string, MrVersion[]>();
  for (const v of versions) byProject.set(v.project_id, [...(byProject.get(v.project_id) ?? []), v]);
  const authorOf = new Map(hits.map((h) => [h.project_id, h.author ?? null]));
  await ctx.emit(changed.map((p) => parseModrinthProject(p, authorOf.get(p.id) ?? null, byProject.get(p.id) ?? [])));
  return changed.length;
}
