  const body = [f.description?.trim(), f.faq?.trim() ? `## FAQ\\n\\n${f.faq.trim()}` : ""].filter(Boolean).join("\\n\\n") || null;
  return {
    ...base,
    body,
    bodyFormat: "markdown",
    sourceUrl: f.source_url || (f.github_path ? `https://github.com/${f.github_path}` : null),
    websiteUrl: f.homepage || null,
