    upstreamUpdatedAt: f.updated_at ? new Date(f.updated_at) : base.upstreamUpdatedAt,
    versions: versions.length ? versions : base.versions,
  };
}

function firstChangelogBlock(c: string | undefined): string | null {
  if (!c) return null;
  const parts = c.split(/-{20,}\\r?\\n/).map((x) => x.trim()).filter(Boolean);
  return (parts[0] ?? c).slice(0, 4000) || null;
}

