    const minDl = Number(process.env.MODSYNC_FACTORIO_MIN_DOWNLOADS ?? 20);
    let produced = 0;
    while (true) {
      if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { page }, done: false };
      // The portal API can only sort by name/created_at/updated_at (not downloads),
      // so a full pass walks every page (~47 requests) and filters locally.
      const sort = "updated_at";
      const r = await ctx.http.json<{ pagination: { page_count: number }; results: FzMod[] }>(
        `${PORTAL}/api/mods?page_size=${PAGE}&page=${page}&sort=${sort}&sort_order=desc`);
      const keep = r.results.filter((m) => (m.downloads_count ?? 0) >= minDl);
      const known = await ctx.known("factorio_portal", keep.map((m) => m.name));
      const flush = async () => {
        if (mods.length) { await ctx.emit(mods); produced += mods.length; mods = []; }
        return Date.now() > ctx.deadline || produced >= ctx.maxMods;
      };
      let mods: NormalizedMod[] = [];
      let interrupted = false;
      for (const m of keep) {
        if (Date.now() > ctx.deadline || (mods.length >= 25 && (await flush()))) { interrupted = true; break; }
        const k = known.get(m.name);
        const upd = m.latest_release?.released_at ? new Date(m.latest_release.released_at) : null;
        if (k && k.hasBody && k.versionCount > 0 && k.upstreamUpdatedAt && upd && +k.upstreamUpdatedAt >= +upd) continue; // unchanged
        try {
          mods.push(parseFactorioFull(await ctx.http.json<FzFull>(`${PORTAL}/api/mods/${encodeURIComponent(m.name)}/full`)));
        } catch {
          mods.push(parseFactorioMod(m)); // list-level data is better than nothing
        }
      }
      await flush();
      if (interrupted) return { cursor: { page }, done: false }; // same page next slice; unchanged mods are skipped via known()
      ctx.log(`factorio page=${page}/${r.pagination.page_count} kept=${keep.length}`);
      page++;
      if (page > r.pagination.page_count || (ctx.mode === "recent" && page > 3)) return { cursor: null, done: true };
    }
  },
};

